function Get-BytesSha256([byte[]]$Bytes) {
    [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($Bytes)).ToLowerInvariant()
}

function Get-TextSha256([string]$Text) {
    Get-BytesSha256 ([Text.Encoding]::UTF8.GetBytes($Text))
}

function Get-FileSha256([string]$Path) {
    Get-BytesSha256 ([IO.File]::ReadAllBytes($Path))
}

if($null-eq('R24NativePath' -as [type])){
Add-Type -TypeDefinition @'
using System;
using System.ComponentModel;
using System.IO;
using System.Runtime.InteropServices;
using System.Text;
public sealed class R24NativePathBinding {
    public string Path;
    public uint VolumeSerial;
    public ulong FileId;
    public bool Directory;
}
public static class R24NativePath {
    const uint READ_ATTRIBUTES=0x80, SHARE=0x7, OPEN_EXISTING=3;
    const uint BACKUP=0x02000000, OPEN_REPARSE=0x00200000;
    static readonly IntPtr INVALID=new IntPtr(-1);
    [StructLayout(LayoutKind.Sequential)] struct INFO { public uint Attr; public System.Runtime.InteropServices.ComTypes.FILETIME C,A,W; public uint Volume,High,Low,Links,IndexHigh,IndexLow; }
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern IntPtr CreateFileW(string n,uint a,uint s,IntPtr sa,uint c,uint f,IntPtr t);
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern uint GetFinalPathNameByHandleW(IntPtr h,StringBuilder b,uint n,uint f);
    [DllImport("kernel32.dll",SetLastError=true)] static extern bool GetFileInformationByHandle(IntPtr h,out INFO i);
    [DllImport("kernel32.dll")] static extern bool CloseHandle(IntPtr h);
    static string Display(string value) { return value.StartsWith(@"\\?\UNC\",StringComparison.Ordinal) ? @"\\"+value.Substring(8) : value.StartsWith(@"\\?\",StringComparison.Ordinal) ? value.Substring(4) : value; }
    public static R24NativePathBinding Bind(string raw,bool directory) {
        if(String.IsNullOrWhiteSpace(raw)||!Path.IsPathFullyQualified(raw)) throw new InvalidOperationException("R24_PATH_NOT_ABSOLUTE");
        string lexical=Path.GetFullPath(raw);
        string root=Path.GetPathRoot(lexical); string current=root;
        foreach(string part in lexical.Substring(root.Length).Split(new[]{Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar},StringSplitOptions.RemoveEmptyEntries)) {
            current=Path.Combine(current,part);
            var attributes=File.GetAttributes(current);
            if((attributes&FileAttributes.ReparsePoint)!=0) throw new InvalidOperationException("R24_PATH_REPARSE_POINT");
        }
        uint flags=(directory?BACKUP:0)|OPEN_REPARSE;
        IntPtr h=CreateFileW(lexical,READ_ATTRIBUTES,SHARE,IntPtr.Zero,OPEN_EXISTING,flags,IntPtr.Zero);
        if(h==INVALID) throw new Win32Exception(Marshal.GetLastWin32Error(),"R24_PATH_OPEN");
        try {
            var b=new StringBuilder(32768); uint length=GetFinalPathNameByHandleW(h,b,(uint)b.Capacity,0);
            if(length==0||length>=b.Capacity) throw new Win32Exception(Marshal.GetLastWin32Error(),"R24_PATH_FINAL");
            INFO info; if(!GetFileInformationByHandle(h,out info)) throw new Win32Exception(Marshal.GetLastWin32Error(),"R24_PATH_IDENTITY");
            string final=Path.GetFullPath(Display(b.ToString()));
            if(!String.Equals(lexical,final,StringComparison.Ordinal)) throw new InvalidOperationException("R24_PATH_ALIAS_OR_CASE");
            bool observedDirectory=(info.Attr&(uint)FileAttributes.Directory)!=0;
            if(observedDirectory!=directory) throw new InvalidOperationException("R24_PATH_KIND");
            return new R24NativePathBinding{Path=final,VolumeSerial=info.Volume,FileId=((ulong)info.IndexHigh<<32)|info.IndexLow,Directory=observedDirectory};
        } finally { CloseHandle(h); }
    }
}
'@
}

function Get-R24NativePathBinding([string]$Path,[switch]$Directory){[R24NativePath]::Bind($Path,[bool]$Directory)}

function Resolve-R24PinnedGitExecutable {
    $pathValue=[string]$script:R24SanitizedEnvironment['PATH'];if([string]::IsNullOrWhiteSpace($pathValue)){throw 'GIT_PIN_PATH_MISSING'}
    foreach($directory in $pathValue.Split([IO.Path]::PathSeparator,[StringSplitOptions]::RemoveEmptyEntries)){
        $candidate=[IO.Path]::Combine($directory.Trim(), 'git.exe')
        if([IO.File]::Exists($candidate)){return (Get-R24NativePathBinding $candidate).Path}
    }
    throw 'GIT_PIN_NOT_FOUND'
}

function Get-CanonicalEnvironmentDigest([Collections.IDictionary]$Environment) {
    $preimage = [Text.StringBuilder]::new()
    foreach ($name in @($Environment.Keys | Sort-Object -CaseSensitive)) {
        [void]$preimage.Append($name).Append("`t").Append([string]$Environment[$name]).Append("`n")
    }
    Get-TextSha256 $preimage.ToString()
}

function Resolve-RepositoryRoot {
    $candidate = [IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'))
    $candidateBinding=Get-R24NativePathBinding $candidate -Directory
    $observation=Invoke-GitObservation 'bootstrap_root_discovery' @('git','-C',$candidateBinding.Path,'rev-parse','--show-toplevel') $candidateBinding.Path
    if($observation.native_exit_u32-ne0){throw 'ROOT_DISCOVERY_FAILED'}
    $resolvedText=Get-TextFromRaw $observation
    $resolvedBinding=Get-R24NativePathBinding $resolvedText -Directory
    if($candidateBinding.Path-cne$resolvedBinding.Path-or$candidateBinding.VolumeSerial-ne$resolvedBinding.VolumeSerial-or$candidateBinding.FileId-ne$resolvedBinding.FileId){throw 'ROOT_BINDING_MISMATCH'}
    $resolvedBinding.Path
}

function Invoke-ExactProcess([string[]]$Argv, [string]$WorkingDirectory) {
    if ($Argv.Count -lt 1) { throw 'EMPTY_ARGV' }
    $psi = [Diagnostics.ProcessStartInfo]::new()
    $psi.FileName = $Argv[0]
    foreach ($argument in $Argv[1..($Argv.Count - 1)]) { [void]$psi.ArgumentList.Add($argument) }
    $psi.WorkingDirectory = $WorkingDirectory
    $psi.UseShellExecute = $false
    $psi.CreateNoWindow = $true
    $psi.RedirectStandardOutput = $true
    $psi.RedirectStandardError = $true
    $process = [Diagnostics.Process]::new()
    $process.StartInfo = $psi
    if (-not $process.Start()) { throw 'PROCESS_START_FAILED' }
    $stdoutTask = $process.StandardOutput.ReadToEndAsync()
    $stderrTask = $process.StandardError.ReadToEndAsync()
    $process.WaitForExit()
    $stdout = $stdoutTask.GetAwaiter().GetResult()
    $stderr = $stderrTask.GetAwaiter().GetResult()
    $bytes = [Text.Encoding]::UTF8.GetByteCount($stdout) + [Text.Encoding]::UTF8.GetByteCount($stderr)
    if ($bytes -gt $StreamLimitBytes) { throw 'OUTPUT_LIMIT_EXCEEDED' }
    [ordered]@{
        argv = $Argv
        native_exit_u32 = [uint32]$process.ExitCode
        portable_exit = if ($process.ExitCode -le 255) { $process.ExitCode } else { 255 }
        stdout = $stdout
        stderr = $stderr
        stdout_sha256 = Get-TextSha256 $stdout
        stderr_sha256 = Get-TextSha256 $stderr
        combined_bytes = $bytes
    }
}

function Assert-StaticSurface {
    $crateManifest = [IO.File]::ReadAllText((Join-Path $RepoRoot 'crates/bastion-boundary-tests/Cargo.toml'))
    $targets = @([regex]::Matches($crateManifest, '(?m)^name = "(source_spine|contract_matrix|property_cases|model_cases|adversarial_cases|hold_closure|no_authority_surface|static_surface)"$'))
    if ($targets.Count -ne 8) { throw 'STATIC_TARGET_INVENTORY' }
    $rustSources = @($ImplementationPaths | Where-Object { $_.EndsWith('.rs',[StringComparison]::Ordinal) })
    if ($rustSources.Count -ne 9) { throw 'STATIC_SOURCE_INVENTORY' }
    $source = ($rustSources | ForEach-Object { [IO.File]::ReadAllText((Join-Path $RepoRoot $_)) }) -join "`n"
    foreach ($token in @('std::fs','std::net','std::env','std::process','std::thread','unsafe {','extern "','todo!','unimplemented!')) {
        if ($source.Contains($token)) { throw "STATIC_FORBIDDEN:$token" }
    }
    if ($crateManifest -match '(?m)^\[(dependencies|dev-dependencies|build-dependencies|features)\]$') { throw 'STATIC_DEPENDENCY_SURFACE' }
    if ($ImplementationPaths.Count -ne 18) { throw 'STATIC_ALLOWLIST' }
    $ordered = @($ImplementationPaths | Sort-Object -CaseSensitive)
    if (($ordered | ConvertTo-Json -Compress) -cne ($ImplementationPaths | ConvertTo-Json -Compress)) { throw 'STATIC_ALLOWLIST_ORDER' }
    if ($source.Contains('exercise_mode(')) { throw 'STATIC_SMOKE_DISPATCH' }
}

function Get-WorkspaceMetadata {
    $result = Invoke-ExactProcess @('cargo','+1.95.0','metadata','--locked','--offline','--no-deps','--format-version','1') $RepoRoot
    if ($result.native_exit_u32 -ne 0) { throw 'METADATA_FAILED' }
    $result.stdout | ConvertFrom-Json
}

function Assert-SupplyChain([string]$Assertion) {
    $metadata = Get-WorkspaceMetadata
    $packages = @($metadata.packages | Sort-Object name)
    if ($packages.Count -ne 2 -or $packages[0].name -ne 'bastion-boundary-tests' -or $packages[1].name -ne 'bastion-review') { throw 'SUPPLY_PACKAGE_SHAPE' }
    if (@($packages | Where-Object { $_.dependencies.Count -ne 0 }).Count -ne 0) { throw 'SUPPLY_DEPENDENCY_EDGE' }
    $tst = $packages | Where-Object name -eq 'bastion-boundary-tests'
    $rev = $packages | Where-Object name -eq 'bastion-review'
    $nodeNames = @($packages.name | Sort-Object -CaseSensitive)
    [object[]]$resolveEdges = @()
    if ($null -ne $metadata.resolve) {
        [object[]]$resolveEdges = @($metadata.resolve.nodes | ForEach-Object { $_.deps } | ForEach-Object { $_ })
    }
    switch ($Assertion) {
        'test_gate::cr_014_fixed_dependency_graph' {
            $zeroDependencyMetadata = [pscustomobject]@{resolve=[pscustomobject]@{nodes=@([pscustomobject]@{deps=@()})}}
            [object[]]$zeroDependencyEdges = @()
            if ($null -ne $zeroDependencyMetadata.resolve) {
                [object[]]$zeroDependencyEdges = @($zeroDependencyMetadata.resolve.nodes | ForEach-Object { $_.deps } | ForEach-Object { $_ })
            }
            if ($zeroDependencyEdges.Count -ne 0) { throw 'SUPPLY_ZERO_DEPENDENCY_REGRESSION' }
            if (($nodeNames | ConvertTo-Json -Compress) -cne '["bastion-boundary-tests","bastion-review"]' -or $resolveEdges.Count -ne 0) { throw 'SUPPLY_RESOLVE_SHAPE' }
        }
        'test_gate::cr_033_package_isolation' {
            if ($tst.manifest_path -eq $rev.manifest_path -or $tst.targets.Count -ne 8 -or $rev.targets.Count -ne 1 -or $tst.dependencies.Count -ne 0 -or $rev.dependencies.Count -ne 0) { throw 'SUPPLY_ISOLATION' }
            $tstProjection = [ordered]@{name=$tst.name;version=$tst.version;edition=$tst.edition;rust_version=$tst.rust_version;manifest_path=$tst.manifest_path;targets=@($tst.targets.name | Sort-Object -CaseSensitive);dependency_count=$tst.dependencies.Count}
            $projectedAgain = [ordered]@{name=(@($packages | Where-Object name -ne 'bastion-review')[0]).name;version=$tst.version;edition=$tst.edition;rust_version=$tst.rust_version;manifest_path=$tst.manifest_path;targets=@($tst.targets.name | Sort-Object -CaseSensitive);dependency_count=$tst.dependencies.Count}
            if (($tstProjection | ConvertTo-Json -Depth 8 -Compress) -cne ($projectedAgain | ConvertTo-Json -Depth 8 -Compress)) { throw 'SUPPLY_REV_REMOVAL_CHANGED_TST' }
        }
        'test_gate::cr_036_dependency_license_advisory' {
            $lock = [IO.File]::ReadAllText((Join-Path $RepoRoot 'Cargo.lock'))
            if ($lock -match '(?m)^(source|checksum|dependencies) = ' -or $lock -match '(?m)^(registry|git)\+' -or @($packages | Where-Object { $_.license -or $_.license_file }).Count -ne 0) { throw 'SUPPLY_EXTERNAL_SUBJECT' }
        }
    }
}

