function ConvertTo-CanonicalJson($Value) {
    $json = ConvertTo-Json -InputObject $Value -Depth 100 -Compress -EscapeHandling EscapeNonAscii
    if ($json.Contains("`r") -or $json.Contains("`n")) { throw 'CANONICAL_JSON_LINE_BREAK' }
    $json
}

function New-DigestedObject([Collections.Specialized.OrderedDictionary]$Fields, [string]$DigestKey) {
    $preimage = ConvertTo-CanonicalJson $Fields
    $copy = [ordered]@{}
    foreach ($key in $Fields.Keys) { $copy[$key] = $Fields[$key] }
    $copy[$DigestKey] = Get-TextSha256 $preimage
    $copy
}

function Write-CreateNewCanonical([string]$Path, $Value) {
    $parent = [IO.Path]::GetDirectoryName($Path)
    if (-not [IO.Directory]::Exists($parent)) { [IO.Directory]::CreateDirectory($parent) | Out-Null }
    $bytes = [Text.Encoding]::UTF8.GetBytes((ConvertTo-CanonicalJson $Value) + "`n")
    $stream = [IO.FileStream]::new($Path,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None,4096,[IO.FileOptions]::WriteThrough)
    try { $stream.Write($bytes,0,$bytes.Length); $stream.Flush($true) } finally { $stream.Dispose() }
    [ordered]@{path=$Path;byte_count=[uint64]$bytes.Length;sha256=(Get-BytesSha256 $bytes)}
}

function Read-StrictJson([string]$Path, [string]$Schema) {
    $bytes = [IO.File]::ReadAllBytes($Path)
    if ($bytes.Length -lt 3 -or $bytes[-1] -ne 10 -or $bytes -contains 13) { throw "NONCANONICAL_JSON:$Path" }
    $text = [Text.Encoding]::UTF8.GetString($bytes,0,$bytes.Length-1)
    $value = $text | ConvertFrom-Json -AsHashtable -Depth 100 -DateKind String
    if ($value.schema -cne $Schema -or (ConvertTo-CanonicalJson $value) -cne $text) { throw "SCHEMA_OR_CANONICAL_MISMATCH:$Path" }
    $value
}

