function Get-R24SupervisorDecisionPointers([string]$ArtifactKind,$PlannedArtifact) {
    if($ArtifactKind-notin@('mode','set')){throw "SUPERVISOR_DISPATCH_KIND:$ArtifactKind"};if($null-eq$PlannedArtifact-or@($PlannedArtifact.reviewer_decisions).Count-ne22){throw "SUPERVISOR_DISPATCH_PLAN:$ArtifactKind"}
    $pointers=@(for($lane=0;$lane-lt22;$lane++){if($null-ne$PlannedArtifact.reviewer_decisions[$lane]){"/reviewer_decisions/$lane"}})
    if($ArtifactKind-ceq'mode'){
        if($PlannedArtifact.successor_kind-notin@('origin','review','execution')){throw 'SUPERVISOR_MODE_TRANSITION_KIND'}
        if($PlannedArtifact.successor_kind-in@('origin','execution')){if($pointers.Count-ne0){throw 'SUPERVISOR_MODE_EXECUTION_RESET'};return @()}
        if($null-eq$PlannedArtifact.predecessor_evidence-or$pointers.Count-lt1){throw 'SUPERVISOR_MODE_REVIEW_TRANSITION'}
    }elseif($null-eq$PlannedArtifact.predecessor_set-and$pointers.Count-ne0){throw 'SUPERVISOR_SET_ORIGIN_TRANSITION'}
    @($pointers)
}

