function Assert-SelfDigest($Value, [string]$DigestKey) {
    $keys = @($Value.Keys)
    if ($keys[-1] -cne $DigestKey) { throw "DIGEST_NOT_LAST:$DigestKey" }
    $copy = [ordered]@{}
    foreach ($key in $keys[0..($keys.Count-2)]) { $copy[$key] = $Value[$key] }
    if ((Get-TextSha256 (ConvertTo-CanonicalJson $copy)) -cne $Value[$DigestKey]) { throw "DIGEST_MISMATCH:$DigestKey" }
}

function New-ExternalDirectory([string]$Prefix, [string]$Parent) {
    $base = if ([string]::IsNullOrEmpty($Parent)) { [IO.Path]::GetTempPath() } else { [IO.Path]::GetFullPath($Parent) }
    if (-not [IO.Directory]::Exists($base)) { [IO.Directory]::CreateDirectory($base) | Out-Null }
    for ($attempt=0; $attempt -lt 128; $attempt++) {
        $candidate = Join-Path $base "$Prefix-$([Guid]::NewGuid().ToString('N'))"
        try { [IO.Directory]::CreateDirectory($candidate) | Out-Null; return [IO.Path]::GetFullPath($candidate) } catch [IO.IOException] { }
    }
    throw 'CREATE_NEW_DIRECTORY_EXHAUSTED'
}

function Invoke-RawProcess([string[]]$Argv, [string]$WorkingDirectory, [Collections.IDictionary]$Environment, [int]$TimeoutMilliseconds = 60000) {
    if ($Argv.Count -eq 0) { throw 'EMPTY_ARGV' }
    $psi=[Diagnostics.ProcessStartInfo]::new();$psi.FileName=$Argv[0]
    foreach($arg in $Argv[1..($Argv.Count-1)]){[void]$psi.ArgumentList.Add($arg)}
    $psi.WorkingDirectory=$WorkingDirectory;$psi.UseShellExecute=$false;$psi.CreateNoWindow=$true;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true
    if ($null -ne $Environment) { $psi.Environment.Clear();foreach($key in $Environment.Keys){$psi.Environment[$key]=[string]$Environment[$key]} }
    $process=[Diagnostics.Process]::new();$process.StartInfo=$psi
    $started=[DateTimeOffset]::UtcNow
    if(-not $process.Start()){throw 'PROCESS_START_FAILED'}
    $stdout=[IO.MemoryStream]::new();$stderr=[IO.MemoryStream]::new()
    $outTask=$process.StandardOutput.BaseStream.CopyToAsync($stdout);$errTask=$process.StandardError.BaseStream.CopyToAsync($stderr)
    if(-not $process.WaitForExit($TimeoutMilliseconds)){try{$process.Kill($true)}catch{};throw 'PROCESS_WALL_LIMIT'}
    $outTask.GetAwaiter().GetResult();$errTask.GetAwaiter().GetResult()
    $outBytes=$stdout.ToArray();$errBytes=$stderr.ToArray();$total=$outBytes.Length+$errBytes.Length
    if($total -gt $StreamLimitBytes){throw 'PROCESS_STREAM_LIMIT'}
    $native=[uint32]$process.ExitCode
    [ordered]@{argv=$Argv;native_exit_u32=$native;portable_exit=if($native-le 255){[int]$native}else{255};stdout_bytes=$outBytes;stderr_bytes=$errBytes;stdout_byte_count=[uint64]$outBytes.Length;stdout_sha256=Get-BytesSha256 $outBytes;stderr_byte_count=[uint64]$errBytes.Length;stderr_sha256=Get-BytesSha256 $errBytes;start_utc=$started.ToString('O');end_utc=[DateTimeOffset]::UtcNow.ToString('O')}
}

