function ConvertTo-R24TotalListCore([string]$Kind,$Items,[uint64]$InitialCount,[AllowNull()][string]$TerminalReason=$null) {
    $retained=[Collections.Generic.List[object]]::new();$hash=[Security.Cryptography.IncrementalHash]::CreateHash([Security.Cryptography.HashAlgorithmName]::SHA256);[uint64]$count=$InitialCount;$overflow=$false
    try{$hash.AppendData([Text.Encoding]::UTF8.GetBytes("schema=preflight-list.v1`nkind=$Kind`n"));foreach($item in $Items){if($retained.Count-lt64){$retained.Add($item)};$hash.AppendData([Text.Encoding]::UTF8.GetBytes((ConvertTo-CanonicalJson $item)+"`n"));if($count-eq[uint64]::MaxValue){$overflow=$true}elseif(-not$overflow){$count++}};if($overflow){$hash.AppendData([Text.Encoding]::UTF8.GetBytes("terminal=count-overflow`n"))}elseif(-not[string]::IsNullOrEmpty($TerminalReason)){$hash.AppendData([Text.Encoding]::UTF8.GetBytes("terminal=$TerminalReason`n"))};$digest=[Convert]::ToHexString($hash.GetHashAndReset()).ToLowerInvariant()}finally{$hash.Dispose()}
    [ordered]@{retained_items=@($retained);total_count=if($overflow){[uint64]::MaxValue}else{$count};count_state=if($overflow){'count-overflow'}else{'exact'};full_set_digest=$digest}
}

