function Get-R24PorcelainInventory([byte[]]$Bytes) {
    $dirty=[Collections.Generic.List[object]]::new();$staged=[Collections.Generic.List[object]]::new();$untracked=[Collections.Generic.List[object]]::new();$ignored=[Collections.Generic.List[object]]::new();$records=[Collections.Generic.List[object]]::new();$start=0
    for($i=0;$i-lt$Bytes.Length;$i++){if($Bytes[$i]-eq0){$length=$i-$start;if($length-eq0){throw 'MALFORMED_PORCELAIN_V2'};$part=[byte[]]::new($length);[Array]::Copy($Bytes,$start,$part,0,$length);$records.Add($part);$start=$i+1}}
    if($start-ne$Bytes.Length){throw 'MALFORMED_PORCELAIN_V2'}
    $seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);$recordIndex=0
    while($recordIndex-lt$records.Count){
        $record=[byte[]]$records[$recordIndex];$kind=[char]$record[0];$fieldCount=if($kind-eq'1'){9}elseif($kind-eq'2'){10}elseif($kind-eq'u'){11}elseif($kind-in@('?','!')){2}else{0};if($fieldCount-eq0-or$record.Length-lt3-or$record[1]-ne32){throw 'MALFORMED_PORCELAIN_V2'}
        $boundaries=[Collections.Generic.List[int]]::new();for($j=0;$j-lt$record.Length-and$boundaries.Count-lt($fieldCount-1);$j++){if($record[$j]-eq32){$boundaries.Add($j)}};if($boundaries.Count-ne($fieldCount-1)-or$boundaries[-1]-ge($record.Length-1)){throw 'MALFORMED_PORCELAIN_V2'}
        $pathStart=$boundaries[-1]+1;$pathBytes=[byte[]]::new($record.Length-$pathStart);[Array]::Copy($record,$pathStart,$pathBytes,0,$pathBytes.Length);$rawPath=New-R24RawGitPath $pathBytes;$pathKey=$rawPath.content;if(-not$seen.Add($pathKey)){throw 'MALFORMED_PORCELAIN_DUPLICATE_PATH'}
        $prefix=[Text.Encoding]::ASCII.GetString($record,0,$pathStart-1);$parts=$prefix.Split(' ');$xy=$null;$hash='(?:[0-9a-f]{40}|0000000000000000000000000000000000000000)';$mode='[0-7]{6}'
        if($kind-in@('?','!')){if($parts.Count-ne1){throw 'MALFORMED_PORCELAIN_V2'};$item=[ordered]@{path=$rawPath;porcelain_tag=[string]$kind};if($kind-eq'?'){$untracked.Add($item)}else{$ignored.Add($item)}}
        else{if(($kind-eq'1'-and$prefix-cnotmatch"^1 [.MADRCUT?!][.MADRCUT?!] .... $mode $mode $mode $hash $hash$")-or($kind-eq'2'-and$prefix-cnotmatch"^2 [.MADRCUT?!][.MADRCUT?!] .... $mode $mode $mode $hash $hash [RC][0-9]{3}$")-or($kind-eq'u'-and$prefix-cnotmatch"^u [.MADRCUT?!][.MADRCUT?!] .... $mode $mode $mode $mode $hash $hash $hash$")){throw 'MALFORMED_PORCELAIN_V2'};$xy=$parts[1];if($xy.Length-ne2){throw 'MALFORMED_PORCELAIN_V2'};$item=[ordered]@{path=$rawPath;porcelain_tag=$xy};if($xy[0]-cne'.'){$staged.Add($item)};if($xy[1]-cne'.'){$dirty.Add($item)};if($kind-eq'2'){$recordIndex++;if($recordIndex-ge$records.Count){throw 'MALFORMED_PORCELAIN_RENAME'};$oldBytes=[byte[]]$records[$recordIndex];if($oldBytes.Length-eq0){throw 'MALFORMED_PORCELAIN_RENAME'};$oldRaw=New-R24RawGitPath $oldBytes;if(-not$seen.Add($oldRaw.content)){throw 'MALFORMED_PORCELAIN_DUPLICATE_PATH'};$item.old_path=$oldRaw}}
        $recordIndex++
    }
    [ordered]@{dirty=@($dirty|ForEach-Object{$_.path});staged=@($staged|ForEach-Object{$_.path});untracked=@($untracked|ForEach-Object{$_.path});ignored=@($ignored|ForEach-Object{$_.path});tagged_dirty=@($dirty);tagged_staged=@($staged);tagged_untracked=@($untracked);tagged_ignored=@($ignored)}
}

function Get-R24PreflightStateFailures($Porcelain,$GeneratedInventory) {
    $found=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);$generated=[ordered]@{};foreach($item in @($GeneratedInventory.items)){$generated[[Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes([string]$item.path))]=[string]$item.porcelain_tag}
    $reasons=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    if(@($Porcelain.dirty).Count-ne0){$reasons.Add('dirty')|Out-Null};if(@($Porcelain.staged).Count-ne0){$reasons.Add('staged')|Out-Null}
    foreach($kind in @('untracked','ignored')){$tag=if($kind-ceq'untracked'){'?'}else{'!'};foreach($item in @($Porcelain["tagged_$kind"])){$key=$item.path.content;if(-not$found.Add($key)-or-not$generated.Contains($key)-or$generated[$key]-cne$tag){$reasons.Add($kind)|Out-Null;if($generated.Contains($key)-and$generated[$key]-cne$tag){$reasons.Add($(if($generated[$key]-ceq'?'){'untracked'}else{'ignored'}))|Out-Null}}}}
    foreach($key in $generated.Keys){if(-not$found.Contains($key)){$expectedKind=if($generated[$key]-ceq'?'){'untracked'}else{'ignored'};$reasons.Add($expectedKind)|Out-Null}}
    Sort-R24UnsignedStrings @($reasons)
