function Get-R24PreflightTerminalReason([string]$Message) {
    if($Message-cmatch'^(MALFORMED_|DUPLICATE_COMPLETE_DELTA_PATH|ACCEPTED_COMPLETE_DELTA_(PATH|DUPLICATE))'){return 'malformed-git-output'}
    if($Message-cmatch'^(GIT_|ROOT_BINDING_MISMATCH|PROCESS_START_FAILED|PROCESS_WALL_LIMIT)'){return 'git-preflight-failed'}
    if($Message-ceq'PROCESS_STREAM_LIMIT'){return 'stream-bound'}
    $null
}

function Resolve-R24ExpectedSha([AllowNull()]$AcceptedExpected,[string]$Path,[object[]]$TreeItems) {
    if($null-ne$AcceptedExpected-and$AcceptedExpected.ContainsKey($Path)){return [string]$AcceptedExpected[$Path].sha256};$tree=@($TreeItems|Where-Object{$_.path-ceq$Path});if($tree.Count-eq1){return [string]$tree[0].sha256};$null
}

function Get-ObservedPreflight([string]$Root,[string]$Commit,[AllowNull()]$AcceptedCompleteDelta=$null) {
    try{return Get-ObservedPreflightCore $Root $Commit $AcceptedCompleteDelta}catch{
        $reason=Get-R24PreflightTerminalReason $_.Exception.Message;if($null-eq$reason){throw}
        $emptyGenerated=[ordered]@{root='context/waves/2026-07-28-bastion-foundation/evidence/wp-tst-001/';items=@();total_count=[uint64]0;manifest_digest=Get-TextSha256 ''}
        $emptyList={param([string]$Kind) ConvertTo-R24TotalListCore $Kind @() 0 $reason}
        $allPartial=@($script:R24PreflightPartialObservations);$terminalIndex=-1
        for($i=0;$i-lt$allPartial.Count;$i++){if($allPartial[$i].native_exit_u32-ne0-or$allPartial[$i].parse_status-ceq'terminal'-or$null-ne$allPartial[$i].reason){$terminalIndex=$i;break}}
        if($terminalIndex-lt0-and$null-ne$script:R24PreflightTerminalCommandId){for($i=0;$i-lt$allPartial.Count;$i++){if($allPartial[$i].command_id-ceq$script:R24PreflightTerminalCommandId){$terminalIndex=$i;break}}}
        if($terminalIndex-lt0){$terminalIndex=$allPartial.Count-1}
        $partial=if($terminalIndex-ge0){@($allPartial[0..$terminalIndex]|ForEach-Object{[ordered]@{command_id=$_.command_id;argv=$_.argv;native_exit_u32=$_.native_exit_u32;portable_exit=$_.portable_exit;stdout_byte_count=$_.stdout_byte_count;stdout_sha256=$_.stdout_sha256;stderr_byte_count=$_.stderr_byte_count;stderr_sha256=$_.stderr_sha256;parse_status=$_.parse_status;reason=$_.reason}})}else{@()}
        if($partial.Count-ne0){$observationReason=switch($reason){'git-preflight-failed'{'command-failed'}'malformed-git-output'{'malformed-output'}'stream-bound'{'stream-bound'}'count-overflow'{'count-overflow'}default{throw 'PREFLIGHT_TERMINAL_REASON_MAP'}};$partial[-1].parse_status='terminal';if($null-eq$partial[-1].reason){$partial[-1].reason=$observationReason}elseif($partial[-1].reason-cne$observationReason){throw 'PREFLIGHT_TERMINAL_REASON_CONFLICT'}}
        $repository=if($null-ne$script:R24PreflightPartialRepository){$script:R24PreflightPartialRepository}else{[ordered]@{repo_root=[IO.Path]::GetFullPath($Root);git_dir=$null;common_dir=$null;index_path=$null;index_before=$null;index_after=$null;common_inputs_before=@();common_inputs_after=@()}}
        $pre=New-DigestedObject ([ordered]@{status='failure';git_observations=$partial;repository_inputs=$repository;generated_paths=$emptyGenerated;rows=&$emptyList 'rows';missing_paths=&$emptyList 'missing_paths';extra_paths=&$emptyList 'extra_paths';dirty_paths=&$emptyList 'dirty_paths';staged_paths=&$emptyList 'staged_paths';untracked_paths=&$emptyList 'untracked_paths';ignored_paths=&$emptyList 'ignored_paths';expected_manifest_digest=$null;actual_manifest_digest=$null;failure_reasons=@($reason)}) 'preflight_digest'
        [ordered]@{preflight=$pre;tree_items=@();artifact_bindings=@();repository_root=$Root;implementation_commit=$Commit;implementation_tree=$null}
    }
}

function validate_path_for_runner([string]$Path) {
    -not [string]::IsNullOrEmpty($Path) -and $Path.Length-le 240 -and -not $Path.StartsWith('/') -and -not $Path.Contains('\') -and -not $Path.Contains(':') -and -not $Path.Contains('%') -and @($Path.Split('/')|Where-Object{$_-eq''-or$_-eq'.'-or$_-eq'..'}).Count-eq 0
}

function Materialize-CommitTree($PreflightResult,[string]$Parent) {
    $root=New-ExternalDirectory 'bastion-tst-materialized' $Parent
    $target=New-ExternalDirectory 'bastion-tst-target' $Parent
    $manifest=[Collections.Generic.List[object]]::new()
    foreach($item in $PreflightResult.tree_items){
        $destination=Join-Path $root $item.path;$parentDir=[IO.Path]::GetDirectoryName($destination)
        if(-not[IO.Directory]::Exists($parentDir)){[IO.Directory]::CreateDirectory($parentDir)|Out-Null}
        $stream=[IO.FileStream]::new($destination,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None,4096,[IO.FileOptions]::WriteThrough)
        try{$stream.Write($item.bytes,0,$item.bytes.Length);$stream.Flush($true)}finally{$stream.Dispose()}
        if((Get-FileSha256 $destination)-cne$item.sha256){throw "MATERIALIZATION_DIGEST:$($item.path)"}
        $manifest.Add([ordered]@{path=$item.path;mode=$item.mode;object_id=$item.object_id;byte_count=$item.byte_count;sha256=$item.sha256})
    }
    $manifestDigest=Get-TextSha256 (($manifest|ForEach-Object{ConvertTo-CanonicalJson $_})-join"`n")
    [ordered]@{root=$root;target=$target;manifest=@($manifest);manifest_digest=$manifestDigest}
}

function Get-TestBinary([string]$SelectedMode) {
    switch($SelectedMode){'L1Static'{'static_surface'}'L2SourceSpine'{'source_spine'}'L2Contract'{'contract_matrix'}'L2Property'{'property_cases'}'L2Model'{'model_cases'}'L2Adversarial'{'adversarial_cases'}'L2HoldClosure'{'hold_closure'}'L2NoAuthority'{'no_authority_surface'}default{$null}}
}

function Get-ControlledId([string]$Assertion) {
    $name=($Assertion-split'::')[-1]
    if($name-match'^cr_([0-9]{3})_'){return "CR-$($Matches[1])"}
    if($name-eq'trace_role_review_steward'){return 'Role review steward'}
    if($name-match'^trace_role_(assurance|editorial|parliament|stakeholders)_(.+)$'){return ".roles/$($Matches[1])/$($Matches[2].Replace('_','-')).md"}
    if($name-eq'trace_role_panel_reviewer_panel'){return '.roles/panel-reviewer/panel.md'}
    if($name-match'^trace_(.+)$'){return $Matches[1].Replace('_','-').ToUpperInvariant()}
    throw "CONTROLLED_ID_UNRESOLVED:$Assertion"
}

function Get-ExecutionPlan([string]$SelectedMode) {
    $phases=[Collections.Generic.List[object]]::new();$flat=[Collections.Generic.List[object]]::new()
    if($Targets.ContainsKey($SelectedMode)){
        $test=Get-TestBinary $SelectedMode;$ordinal=1
        $phase=[ordered]@{phase_ordinal=1;phase_id="PHASE-$SelectedMode-01";kind='targets';tool_version_indices=@(0);argv=@('cargo','+1.95.0','test','-p','bastion-boundary-tests','--locked','--offline','--test',$test,'<ASSERTION>','--','--exact','--test-threads=1','--nocapture');target_first=0;target_count=$Targets[$SelectedMode].Count}
        $invocations=[Collections.Generic.List[object]]::new()
        foreach($assertion in $Targets[$SelectedMode]){
            $argv=@('cargo','+1.95.0','test','-p','bastion-boundary-tests','--locked','--offline','--test',$test,$assertion,'--','--exact','--test-threads=1','--nocapture')
            $controlled=Get-ControlledId $assertion
            $entry=[ordered]@{phase=$phase;target_ordinal=$ordinal;controlled_id=$controlled;assertion=$assertion;argv=$argv};$invocations.Add($entry);$flat.Add($argv);$ordinal++
        }
        $phase.invocations=@($invocations);$phases.Add($phase)
        if($SelectedMode-eq'L1Static'){
            $argv=@('pwsh','-NoLogo','-NoProfile','-NonInteractive','-File','tools/test_gate.ps1','-AssertPhase','assert-static-surface')
            $phase2=[ordered]@{phase_ordinal=2;phase_id='PHASE-L1Static-02';kind='command';tool_version_indices=@(1);argv=$argv;target_first=$null;target_count=$null;invocations=@([ordered]@{phase=$null;target_ordinal=$null;controlled_id=$null;assertion='assert-static-surface';argv=$argv})};$phase2.invocations[0].phase=$phase2;$phases.Add($phase2);$flat.Add($argv)
        }
    }elseif($SelectedMode-eq'L1SupplyChain'){
        $cargo=@('cargo','+1.95.0','metadata','--locked','--offline','--no-deps','--format-version','1')
        $p1=[ordered]@{phase_ordinal=1;phase_id='PHASE-L1SupplyChain-01';kind='command';tool_version_indices=@(0);argv=$cargo;target_first=$null;target_count=$null;invocations=@()};$p1.invocations=@([ordered]@{phase=$p1;target_ordinal=$null;controlled_id=$null;assertion='cargo-metadata';argv=$cargo});$phases.Add($p1);$flat.Add($cargo)
        $assertions=@('test_gate::cr_014_fixed_dependency_graph','test_gate::cr_033_package_isolation','test_gate::cr_036_dependency_license_advisory');$items=[Collections.Generic.List[object]]::new();$o=1
        foreach($assertion in $assertions){$argv=@('pwsh','-NoLogo','-NoProfile','-NonInteractive','-File','tools/test_gate.ps1','-AssertTarget',$assertion);$items.Add([ordered]@{phase=$null;target_ordinal=$o;controlled_id=Get-ControlledId $assertion;assertion=$assertion;argv=$argv});$flat.Add($argv);$o++}
        $p2=[ordered]@{phase_ordinal=2;phase_id='PHASE-L1SupplyChain-02';kind='targets';tool_version_indices=@(1);argv=@('pwsh','-NoLogo','-NoProfile','-NonInteractive','-File','tools/test_gate.ps1','-AssertTarget','<ASSERTION>');target_first=0;target_count=3;invocations=@($items)};foreach($i in $p2.invocations){$i.phase=$p2};$phases.Add($p2)
    }else{
        $commands=@(Get-ModeCommand $SelectedMode);$o=1
        foreach($argv in $commands){$phase=[ordered]@{phase_ordinal=$o;phase_id=('PHASE-{0}-{1:d2}'-f$SelectedMode,$o);kind='command';tool_version_indices=@(0);argv=$argv;target_first=$null;target_count=$null;invocations=@()};$phase.invocations=@([ordered]@{phase=$phase;target_ordinal=$null;controlled_id=$null;assertion=$null;argv=$argv});$phases.Add($phase);$flat.Add($argv);$o++}
    }
    [ordered]@{phases=@($phases);exact_argv=@($flat)}
}

function Assert-R24ExecutionPlan([string]$SelectedMode,$Plan) {
    if($SelectedMode-notin$ModeOrder-or$null-eq$Plan-or@($Plan.phases).Count-eq0){throw "EXECUTION_PLAN_MODE:$SelectedMode"}
    $expectedFlat=[Collections.Generic.List[object]]::new()
    if($Targets.ContainsKey($SelectedMode)){
        $test=Get-TestBinary $SelectedMode;$targetPhase=$Plan.phases[0]
        if($targetPhase.phase_ordinal-ne1-or$targetPhase.phase_id-cne"PHASE-$SelectedMode-01"-or$targetPhase.kind-cne'targets'-or$targetPhase.target_count-ne$Targets[$SelectedMode].Count-or@($targetPhase.invocations).Count-ne$Targets[$SelectedMode].Count){throw "EXECUTION_PLAN_TARGET_PHASE:$SelectedMode"}
        for($i=0;$i-lt$Targets[$SelectedMode].Count;$i++){
            $assertion=$Targets[$SelectedMode][$i];$expectedArgv=@('cargo','+1.95.0','test','-p','bastion-boundary-tests','--locked','--offline','--test',$test,$assertion,'--','--exact','--test-threads=1','--nocapture');$invocation=$targetPhase.invocations[$i]
            if($invocation.target_ordinal-ne($i+1)-or$invocation.assertion-cne$assertion-or$invocation.controlled_id-cne(Get-ControlledId $assertion)-or(ConvertTo-CanonicalJson @($invocation.argv))-cne(ConvertTo-CanonicalJson $expectedArgv)){throw "EXECUTION_PLAN_TARGET_ALLOCATION:${SelectedMode}:$i"};$expectedFlat.Add($expectedArgv)
        }
        $expectedPhaseCount=if($SelectedMode-ceq'L1Static'){2}else{1};if(@($Plan.phases).Count-ne$expectedPhaseCount){throw "EXECUTION_PLAN_PHASE_COUNT:$SelectedMode"}
        if($SelectedMode-ceq'L1Static'){$expected=@('pwsh','-NoLogo','-NoProfile','-NonInteractive','-File','tools/test_gate.ps1','-AssertPhase','assert-static-surface');if((ConvertTo-CanonicalJson @($Plan.phases[1].invocations[0].argv))-cne(ConvertTo-CanonicalJson $expected)){throw 'EXECUTION_PLAN_STATIC_COMMAND'};$expectedFlat.Add($expected)}
    }elseif($SelectedMode-ceq'L1SupplyChain'){
        $assertions=@('test_gate::cr_014_fixed_dependency_graph','test_gate::cr_033_package_isolation','test_gate::cr_036_dependency_license_advisory');if(@($Plan.phases).Count-ne2-or@($Plan.phases[1].invocations).Count-ne3){throw 'EXECUTION_PLAN_SUPPLY_PHASES'}
        $metadata=@('cargo','+1.95.0','metadata','--locked','--offline','--no-deps','--format-version','1');if((ConvertTo-CanonicalJson @($Plan.phases[0].invocations[0].argv))-cne(ConvertTo-CanonicalJson $metadata)){throw 'EXECUTION_PLAN_SUPPLY_METADATA'};$expectedFlat.Add($metadata)
        for($i=0;$i-lt3;$i++){$assertion=$assertions[$i];$expected=@('pwsh','-NoLogo','-NoProfile','-NonInteractive','-File','tools/test_gate.ps1','-AssertTarget',$assertion);$invocation=$Plan.phases[1].invocations[$i];if($invocation.target_ordinal-ne($i+1)-or$invocation.assertion-cne$assertion-or$invocation.controlled_id-cne(Get-ControlledId $assertion)-or(ConvertTo-CanonicalJson @($invocation.argv))-cne(ConvertTo-CanonicalJson $expected)){throw "EXECUTION_PLAN_SUPPLY_TARGET:$i"};$expectedFlat.Add($expected)}
    }else{
        $commands=@(Get-ModeCommand $SelectedMode);if(@($Plan.phases).Count-ne$commands.Count){throw "EXECUTION_PLAN_COMMAND_COUNT:$SelectedMode"};for($i=0;$i-lt$commands.Count;$i++){if($Plan.phases[$i].phase_ordinal-ne($i+1)-or$Plan.phases[$i].kind-cne'command'-or(ConvertTo-CanonicalJson @($Plan.phases[$i].invocations[0].argv))-cne(ConvertTo-CanonicalJson @($commands[$i]))){throw "EXECUTION_PLAN_COMMAND:${SelectedMode}:$i"};$expectedFlat.Add($commands[$i])}
    }
    if((ConvertTo-CanonicalJson @($Plan.exact_argv))-cne(ConvertTo-CanonicalJson @($expectedFlat))){throw "EXECUTION_PLAN_EXACT_ARGV:$SelectedMode"}
}

function Assert-R24AllModeExecutionPlans {
    foreach($selected in $ModeOrder){$plan=Get-ExecutionPlan $selected;Assert-R24ExecutionPlan $selected $plan}
}

