function Get-R24LedgerSuffixKeys([string]$Kind,$Suffix) {
    if($Kind-ceq'run-start'){return @('start_utc')}
    if($Kind-cmatch'^phase-[0-9]{2}-start$'){if($Suffix.phase_kind-ceq'command'){return @('phase_ordinal','phase_id','phase_kind','argv','process_id','process_creation_filetime','job_name','job_configuration_digest','start_utc')}elseif($Suffix.phase_kind-ceq'targets'){return @('phase_ordinal','phase_id','phase_kind','argv','start_utc')}else{throw 'LEDGER_PHASE_KIND'}}
    if($Kind-cmatch'^target-[0-9]{3}-start$'){return @('phase_ordinal','phase_id','target_ordinal','controlled_id','assertion','argv','process_id','process_creation_filetime','job_name','job_configuration_digest','start_utc')}
    if($Kind-cmatch'^target-[0-9]{3}-completion$'){return @('phase_ordinal','phase_id','target_ordinal','controlled_id','assertion','argv','paired_start_digest','native_exit_u32','portable_exit','state','reason','stdout_sha256','stderr_sha256','end_utc')}
    if($Kind-cmatch'^target-[0-9]{3}-recovery$'){return @('phase_ordinal','phase_id','target_ordinal','controlled_id','assertion','argv','paired_start_digest','termination_observation','native_exit_u32','portable_exit','state','reason','stdout_sha256','stderr_sha256','recovery_utc')}
    if($Kind-cmatch'^phase-[0-9]{2}-completion$'){return @('phase_ordinal','phase_id','phase_kind','argv','paired_start_digest','native_exit_u32','portable_exit','state','reason','end_utc')}
    if($Kind-cmatch'^phase-[0-9]{2}-recovery$'){return @('phase_ordinal','phase_id','phase_kind','argv','paired_start_digest','termination_observation','native_exit_u32','portable_exit','state','reason','recovery_utc')}
    if($Kind-ceq'run-completion'){return @('paired_start_digest','native_exit_u32','portable_exit','state','reason','end_utc')}
    if($Kind-ceq'run-recovery'){return @('paired_start_digest','termination_observation','native_exit_u32','portable_exit','state','reason','recovery_utc')}
    throw 'LEDGER_RECORD_KIND'
}

function Assert-R24LedgerUtc([string]$Value) {$parsed=[DateTimeOffset]::MinValue;if(-not[DateTimeOffset]::TryParseExact($Value,'O',[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::None,[ref]$parsed)-or$parsed.Offset-ne[TimeSpan]::Zero){throw 'LEDGER_UTC'}}

function Assert-R24LedgerProcessIdentity($Writer,$Suffix) {
    if([uint64]$Suffix.process_id-lt1-or[uint64]$Suffix.process_creation_filetime-lt1){throw 'LEDGER_PROCESS_IDENTITY'};$nameHash=Get-TextSha256 $Writer.run_id;$expectedName="Local\BAS-TST-$($nameHash.Substring(0,32))";if($Suffix.job_name-cne$expectedName){throw 'LEDGER_JOB_NAME'};$keyDigest=Get-TextSha256 "completion-key=$($Writer.run_id)`n";$preimage="name=$expectedName`nkill_on_close=true`nhard_limit_flags=JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE|JOB_OBJECT_LIMIT_JOB_MEMORY`njob_memory_bytes=1073741824`nprocess_memory_bytes=null`ncompletion_key_digest=$keyDigest`nnotification_limit_flags=JOB_OBJECT_LIMIT_JOB_MEMORY_HIGH`nnotification_job_memory_bytes=1073741824`nrun_id=$($Writer.run_id)`n";if($Suffix.job_configuration_digest-cne(Get-TextSha256 $preimage)){throw 'LEDGER_JOB_CONFIGURATION'}
}

function Assert-R24LedgerRecordCandidate($Writer,[string]$Kind,$Suffix) {
    if($Writer.records.Count-ne0-and$Writer.predecessor-cne$Writer.records[-1].record.record_digest){throw 'LEDGER_PREDECESSOR_STATE'};$expected=@(Get-R24LedgerSuffixKeys $Kind $Suffix);if((ConvertTo-CanonicalJson @($Suffix.Keys))-cne(ConvertTo-CanonicalJson @($expected))){throw "LEDGER_SUFFIX_KEYS:$Kind"};$timeKey=@(@('start_utc','end_utc','recovery_utc')|Where-Object{$Suffix.Contains($_)});if($timeKey.Count-ne1){throw 'LEDGER_TIME_KEY'};Assert-R24LedgerUtc ([string]$Suffix[$timeKey[0]])
    if($Kind-ceq'run-start'){if($Writer.ordinal-ne0-or$Writer.run_started-or$null-ne$Writer.open_phase){throw 'LEDGER_RUN_START_SEQUENCE'};return}
    if(-not$Writer.run_started-or$Writer.run_closed){throw 'LEDGER_RUN_SEQUENCE'}
    if($Kind-cmatch'^phase-([0-9]{2})-start$'){if($null-ne$Writer.open_phase-or$null-ne$Writer.open_target-or[int]$Matches[1]-ne$Writer.next_phase-or[int]$Suffix.phase_ordinal-ne$Writer.next_phase-or$Suffix.phase_id-cne("PHASE-$($Writer.mode)-{0:d2}"-f$Writer.next_phase)){throw 'LEDGER_PHASE_START_SEQUENCE'};if($Suffix.phase_kind-ceq'command'){Assert-R24LedgerProcessIdentity $Writer $Suffix};return}
    if($Kind-cmatch'^target-([0-9]{3})-start$'){if($null-eq$Writer.open_phase-or$Writer.open_phase.phase_kind-cne'targets'-or$null-ne$Writer.open_target-or[int]$Matches[1]-ne$Writer.next_target-or[int]$Suffix.target_ordinal-ne$Writer.next_target-or$Suffix.phase_id-cne$Writer.open_phase.phase_id){throw 'LEDGER_TARGET_START_SEQUENCE'};Assert-R24LedgerProcessIdentity $Writer $Suffix;return}
    if(-not$Suffix.Contains('paired_start_digest')-or$Writer.paired.Contains([string]$Suffix.paired_start_digest)){throw 'LEDGER_PAIR_DUPLICATE'}
    if($Kind-cmatch'^target-[0-9]{3}-(completion|recovery)$'){if($null-eq$Writer.open_target-or$Suffix.paired_start_digest-cne$Writer.open_target.record_digest-or$Suffix.phase_id-cne$Writer.open_target.phase_id-or$Suffix.controlled_id-cne$Writer.open_target.controlled_id-or$Suffix.assertion-cne$Writer.open_target.assertion){throw 'LEDGER_TARGET_PAIR'}
    }elseif($Kind-cmatch'^phase-[0-9]{2}-(completion|recovery)$'){if($null-eq$Writer.open_phase-or$null-ne$Writer.open_target-or$Suffix.paired_start_digest-cne$Writer.open_phase.record_digest-or$Suffix.phase_id-cne$Writer.open_phase.phase_id-or$Suffix.phase_kind-cne$Writer.open_phase.phase_kind){throw 'LEDGER_PHASE_PAIR'}
    }elseif($Kind-cmatch'^run-(completion|recovery)$'){if($null-ne$Writer.open_phase-or$null-ne$Writer.open_target-or$Suffix.paired_start_digest-cne$Writer.records[0].record.record_digest){throw 'LEDGER_RUN_PAIR'}}else{throw 'LEDGER_TERMINAL_KIND'}
    if($Suffix.Contains('native_exit_u32')){if([uint64]$Suffix.native_exit_u32-gt[uint32]::MaxValue-or[int]$Suffix.portable_exit-lt0-or[int]$Suffix.portable_exit-gt255-or[int]$Suffix.portable_exit-ne$(if([uint64]$Suffix.native_exit_u32-le255){[int]$Suffix.native_exit_u32}else{255})){throw 'LEDGER_EXIT_PROJECTION'}}
    $pairs=@{ 'assertion-passed'='passed';'assertion-failed'='failed';'target-held'='held';'unexpected-exit'='failed';'all-children-passed'='passed';'command-passed'='passed';'child-failed'='failed';'child-held'='held';'command-failed'='failed';'all-phases-passed'='passed';'phase-failed'='failed';'phase-held'='held'};if($Kind-like'*-recovery') {if($Suffix.state-cne'failed'-or$Suffix.reason-notin@('timeout','wall-limit','memory-limit','output-limit','bound-kill','crash','unexpected-exit','supervisor-loss','ledger-corruption')-or$Suffix.termination_observation.kind-cne$Suffix.reason){throw 'LEDGER_RECOVERY_STATE_REASON'}}elseif(-not$pairs.ContainsKey([string]$Suffix.reason)-or$Suffix.state-cne$pairs[[string]$Suffix.reason]){throw 'LEDGER_COMPLETION_STATE_REASON'}
}

function Update-R24LedgerWriterState($Writer,[string]$Kind,$Record) {
    if($Kind-ceq'run-start'){$Writer.run_started=$true;return};if($Kind-like'phase-*-start'){$Writer.open_phase=$Record;$Writer.next_target=1;return};if($Kind-like'target-*-start'){$Writer.open_target=$Record;return};if($Kind-like'*-completion'-or$Kind-like'*-recovery'){$Writer.paired.Add([string]$Record.paired_start_digest)|Out-Null};if($Kind-like'target-*-completion'-or$Kind-like'target-*-recovery'){$Writer.open_target=$null;$Writer.next_target++;return};if($Kind-like'phase-*-completion'-or$Kind-like'phase-*-recovery'){$Writer.open_phase=$null;$Writer.next_phase++;return};if($Kind-like'run-*'){$Writer.run_closed=$true;return}
}

function Add-LedgerRecord($Writer,[string]$Kind,[Collections.Specialized.OrderedDictionary]$Suffix) {
    Assert-R24LedgerRecordCandidate $Writer $Kind $Suffix
    $base=[ordered]@{schema='test-gate-ledger.v8';record_kind=$Kind;wp_id=$WpId;wp_revision=$WpRevision;wp_digest=$WpDigest;lineage_binding=$Writer.lineage;acceptance_commit=$AcceptanceCommit;corrective_entry_commit=$EntryCommit;failed_implementation_commit='7e4591838dfffdc8d1fc35f0e97e77133a56490b';implementation_commit=$Writer.implementation;mode=$Writer.mode;execution_id=$Writer.execution_id;execution_evidence_version=$Writer.execution_version;run_attempt=$Writer.attempt;run_id=$Writer.run_id;ordinal=$Writer.ordinal;predecessor_digest=$Writer.predecessor}
    foreach($key in $Suffix.Keys){$base[$key]=$Suffix[$key]}
    $record=New-DigestedObject $base 'record_digest'
    $file="r$($Writer.ordinal.ToString('0000'))-$Kind.json";$path=Join-Path $Writer.root $file
    if($null-ne$Writer.session){if([string]::IsNullOrWhiteSpace($Writer.logical_root)-or[string]::IsNullOrWhiteSpace($Writer.publication_root)){throw 'LEDGER_CANONICAL_WRITER_BINDING'};Write-R24CanonicalLogicalArtifact $Writer.session $Writer.publication_root "$($Writer.logical_root)/$file" $record|Out-Null}else{Write-CreateNewCanonical $path $record|Out-Null}
    $Writer.records.Add([ordered]@{filename=$file;path=$path;record=$record});$Writer.predecessor=$record.record_digest;$Writer.ordinal++;Update-R24LedgerWriterState $Writer $Kind $record
    $record
}

function Get-LedgerBinding($Writer) {
    $records=@($Writer.records);if($records.Count-lt 2){throw 'LEDGER_TOO_SHORT'}
    $preimage=($records|ForEach-Object{"$($_.filename)`t$($_.record.record_digest)`n"})-join''
    [ordered]@{execution_id=$Writer.execution_id;execution_ordinal=1;execution_evidence_version=$Writer.execution_version;run_id=$Writer.run_id;root_path=if([string]::IsNullOrWhiteSpace($Writer.logical_root)){$Writer.root.Replace('\','/')}else{$Writer.logical_root};run_attempt=$Writer.attempt;first_record_digest=$records[0].record.record_digest;last_record_digest=$records[-1].record.record_digest;record_count=$records.Count;aggregate_digest=Get-TextSha256 $preimage}
