function Assert-LedgerChain([string]$Root) {
    $files=@(Get-ChildItem -LiteralPath $Root -File | Sort-Object Name);$records=[Collections.Generic.List[object]]::new()
    if($files.Count-lt 2){throw 'LEDGER_MISSING'};$prior=$null;$ordinal=0
    foreach($file in $files){
        if($file.Name-notmatch'^r([0-9]{4})-(run-start|phase-[0-9]{2}-(start|completion|recovery)|target-[0-9]{3}-(start|completion|recovery)|run-(completion|recovery))[.]json$'-or[int]$Matches[1]-ne$ordinal){throw 'LEDGER_FILENAME_SEQUENCE'}
        $record=Read-StrictJson $file.FullName 'test-gate-ledger.v8';Assert-SelfDigest $record 'record_digest';Assert-R24RetainedLedgerRecordShape $record
        if($record.wp_id-cne$WpId-or$record.wp_revision-cne$WpRevision-or$record.wp_digest-cne$WpDigest-or$record.acceptance_commit-cne$AcceptanceCommit-or$record.corrective_entry_commit-cne$EntryCommit-or$record.failed_implementation_commit-cne'7e4591838dfffdc8d1fc35f0e97e77133a56490b'-or$record.lineage_binding.corrective_implementation_commit-cne$record.implementation_commit){throw 'LEDGER_R24_IDENTITY'}
        if($file.BaseName.Substring(6)-cne$record.record_kind){throw 'LEDGER_KIND_FILENAME_MISMATCH'}
        if($record.ordinal-ne$ordinal-or$record.predecessor_digest-cne$prior){throw 'LEDGER_CHAIN'}
        $records.Add($record);$prior=$record.record_digest;$ordinal++
    }
    if($records[0].record_kind-cne'run-start'-or$records[-1].record_kind-notin@('run-completion','run-recovery')-or$records[-1].paired_start_digest-cne$records[0].record_digest){throw 'LEDGER_RUN_ALGEBRA'}
    $cursor=1;$phaseOrdinal=1
    while($cursor-lt$records.Count-1){$phaseStart=$records[$cursor];if($phaseStart.record_kind-cne("phase-{0:d2}-start"-f$phaseOrdinal)-or$phaseStart.phase_ordinal-ne$phaseOrdinal-or$phaseStart.phase_id-cne("PHASE-$($records[0].mode)-{0:d2}"-f$phaseOrdinal)){throw 'LEDGER_PHASE_START_ALGEBRA'};$cursor++;$targetOrdinal=1
        while($cursor-lt$records.Count-1-and$records[$cursor].record_kind-ceq("target-{0:d3}-start"-f$targetOrdinal)){$targetStart=$records[$cursor];if($targetStart.phase_ordinal-ne$phaseOrdinal-or$targetStart.phase_id-cne$phaseStart.phase_id-or$targetStart.target_ordinal-ne$targetOrdinal){throw 'LEDGER_TARGET_START_ALGEBRA'};$cursor++;if($cursor-ge$records.Count-1){throw 'LEDGER_TARGET_UNPAIRED'};$targetTerminal=$records[$cursor];if($targetTerminal.record_kind-notin@(("target-{0:d3}-completion"-f$targetOrdinal),("target-{0:d3}-recovery"-f$targetOrdinal))-or$targetTerminal.paired_start_digest-cne$targetStart.record_digest-or$targetTerminal.phase_id-cne$phaseStart.phase_id-or$targetTerminal.controlled_id-cne$targetStart.controlled_id-or$targetTerminal.assertion-cne$targetStart.assertion-or(ConvertTo-CanonicalJson @($targetTerminal.argv))-cne(ConvertTo-CanonicalJson @($targetStart.argv))){throw 'LEDGER_TARGET_TERMINAL_ALGEBRA'};if($targetTerminal.record_kind-like'*-recovery'){Assert-R24RecoveryRecordProjection $targetTerminal};$cursor++;$targetOrdinal++}
        if($cursor-ge$records.Count-1){throw 'LEDGER_PHASE_UNPAIRED'};$phaseTerminal=$records[$cursor];if($phaseTerminal.record_kind-notin@(("phase-{0:d2}-completion"-f$phaseOrdinal),("phase-{0:d2}-recovery"-f$phaseOrdinal))-or$phaseTerminal.paired_start_digest-cne$phaseStart.record_digest-or$phaseTerminal.phase_id-cne$phaseStart.phase_id-or(ConvertTo-CanonicalJson @($phaseTerminal.argv))-cne(ConvertTo-CanonicalJson @($phaseStart.argv))){throw 'LEDGER_PHASE_TERMINAL_ALGEBRA'};if($phaseTerminal.record_kind-like'*-recovery'){Assert-R24RecoveryRecordProjection $phaseTerminal};$cursor++;$phaseOrdinal++
    }
    if($cursor-ne$records.Count-1){throw 'LEDGER_SCOPE_ALGEBRA'};if($records[-1].record_kind-ceq'run-recovery'){Assert-R24RecoveryRecordProjection $records[-1]}
    $preimage=for($i=0;$i-lt$files.Count;$i++){"$($files[$i].Name)`t$($records[$i].record_digest)`n"};$binding=[ordered]@{execution_id=$records[0].execution_id;execution_ordinal=1;execution_evidence_version=$records[0].execution_evidence_version;run_id=$records[0].run_id;root_path=[IO.Path]::GetFullPath($Root).Replace('\','/');run_attempt=$records[0].run_attempt;first_record_digest=$records[0].record_digest;last_record_digest=$records[-1].record_digest;record_count=$records.Count;aggregate_digest=Get-TextSha256 ($preimage-join'')};[ordered]@{files=$files;records=@($records);binding=$binding}
}

