function Convert-R24FaultSeamEvents([object[]]$Rows,[string]$Source,[string]$Family) {
    if($Family-notin@('job','durable')){throw 'FAULT_SEAM_FAMILY'}
    $result=[Collections.Generic.List[object]]::new();$sequence=[uint64]0
    $jobStages=@('completion-port','create','open','query','process','duplicate','assign','terminate','wait','close')
    $durableStages=@('create','write','file-flush','duplicate','original-close','parent-open','parent-flush','parent-ntflush','parent-close','retained-close')
    $expectedStages=if($Family-ceq'job'){$jobStages}else{$durableStages};$cleanupApi=if($Family-ceq'job'){'JobFault.Cleanup'}else{'DurableArtifact.Cleanup'}
    foreach($row in @($Rows)){
        if([string]::IsNullOrWhiteSpace([string]$row.Api)-or$null-eq$row.Detail-or$row.Error-lt0){throw 'FAULT_SEAM_ROW'}
        $detail=[string]$row.Detail;$stageMatch=[regex]::Match($detail,'(?:^|:)injected_stage=([^:]+)(?::|$)')
        if(([string]$row.Api)-ceq$cleanupApi){
            if(-not[bool]$row.Ok-or[uint32]$row.Error-ne0-or$detail-notlike'*nonpromotable=true*'){throw 'FAULT_SEAM_CLEANUP'}
            $kind='cleanup'
        } else {
            if([bool]$row.Ok-or[uint32]$row.Error-ne5-or$detail-notlike'*production_wrapper=true:single_use=true:nonpromotable=true*'-or-not$stageMatch.Success-or$stageMatch.Groups[1].Value-notin$expectedStages){throw 'FAULT_SEAM_INJECTION'}
            $kind='injected-call'
        }
        $result.Add([ordered]@{sequence=$sequence;family=$Family;kind=$kind;recorded_api=[string]$row.Api;result=[uint32]$(if([bool]$row.Ok){1}else{0});last_error=[uint32]$row.Error;source=$Source;detail=$detail});$sequence++
    }
    foreach($stage in $expectedStages){$injected=@($result|Where-Object{$_.kind-ceq'injected-call'-and$_.detail-like"*injected_stage=$stage*"});if($injected.Count-ne1){throw "FAULT_SEAM_STAGE_CARDINALITY:${Family}:$stage"}}
    $cleanup=@($result|Where-Object{$_.kind-ceq'cleanup'});if($cleanup.Count-ne$expectedStages.Count-or$result.Count-ne(2*$expectedStages.Count)){throw "FAULT_SEAM_CLEANUP_CARDINALITY:$Family"}
    @($result)
}

