    $items=[Collections.Generic.List[object]]::new();foreach($record in @([Text.Encoding]::UTF8.GetString($bytes).Split([char]0,[StringSplitOptions]::RemoveEmptyEntries))){if($record-notmatch'^(100644|100755) blob ([0-9a-f]{40})\t(.+)$'){throw 'RAW_TREE_ENTRY_UNSUPPORTED'};$mode=$Matches[1];$oid=$Matches[2];$path=$Matches[3];if(-not(validate_path_for_runner $path)){throw "RAW_TREE_PATH:$path"};$blob=Invoke-GitObservation 'fixture_blob_bytes' ($semantic+@('cat-file','blob',$oid)) $RepoRoot;if($blob.native_exit_u32-ne0){throw 'RAW_TREE_BLOB_FAILED'};$items.Add([ordered]@{mode=$mode;object_id=$oid;path=$path;byte_count=$blob.stdout_byte_count;sha256=$blob.stdout_sha256;bytes=[byte[]]$blob.raw.stdout_bytes})}
    [ordered]@{items=@($items);invocation_count=$items.Count+1}
}

function Invoke-R24FiveRootMaterializationProbe([string]$Parent,[string]$SourceCommit=$EntryCommit) {
    if($SourceCommit-cnotmatch'^[0-9a-f]{40}$'){throw 'FIVE_ROOT_SOURCE_COMMIT'}
    $materialRoot=New-ExternalDirectory 'five-root-materialization' $Parent;$targetRoot=New-ExternalDirectory 'five-root-target' $Parent
    $gitDir=Invoke-R24GitText 'watch_git_dir' @('git','-C',$RepoRoot,'rev-parse','--absolute-git-dir') $RepoRoot;$commonRaw=Invoke-R24GitText 'watch_common_dir' @('git','-C',$RepoRoot,'rev-parse','--git-common-dir') $RepoRoot;$commonDir=if([IO.Path]::IsPathRooted($commonRaw)){[IO.Path]::GetFullPath($commonRaw)}else{[IO.Path]::GetFullPath((Join-Path $RepoRoot $commonRaw))}
    $roots=[ordered]@{worktree=$RepoRoot;'worktree-git'=$gitDir;'common-git'=$commonDir;materialization=$materialRoot;'cargo-target'=$targetRoot}
    $watchers=@();$subscriptions=@();$events=[Collections.Generic.List[object]]::new();$sequence=[uint64]0;$held=@()
    try {
        foreach($name in $roots.Keys){$watcher=[IO.FileSystemWatcher]::new($roots[$name]);$watcher.IncludeSubdirectories=$true;$watcher.InternalBufferSize=65536;$watcher.NotifyFilter=[IO.NotifyFilters]::FileName-bor[IO.NotifyFilters]::DirectoryName-bor[IO.NotifyFilters]::LastWrite-bor[IO.NotifyFilters]::Size;$sid="BAS-TST-5-$name-$([Guid]::NewGuid().ToString('N'))";$subscriptions+=Register-ObjectEvent $watcher Created -SourceIdentifier "$sid-created";$subscriptions+=Register-ObjectEvent $watcher Error -SourceIdentifier "$sid-error";$watcher.EnableRaisingEvents=$true;$watchers+=[ordered]@{name=$name;watcher=$watcher;created="$sid-created";error="$sid-error"};$events.Add([ordered]@{sequence=$sequence;source=$name;action='watch-start';raw_path=$null;byte_count=$null;content_sha256=$null});$sequence++}
        $holdPaths=@($ImplementationPaths|ForEach-Object{Join-Path $RepoRoot $_})+@((Join-Path $RepoRoot 'docs/vtrace/WP_TST_001.md'),(Join-Path $RepoRoot 'context/waves/2026-07-28-bastion-foundation/pulses/pulse-44-wp-tst-001-r24-corrective-lineage-candidate.md'),(Join-Path $RepoRoot 'context/waves/2026-07-28-bastion-foundation/pulses/pulse-45-wp-tst-001-r24-acceptance.md'),(Join-Path $RepoRoot 'context/waves/2026-07-28-bastion-foundation/pulses/pulse-46-wp-tst-001-r24-corrective-entry.md'),(Join-Path $gitDir 'index'))
        $holdPaths=@($holdPaths|Where-Object{[IO.File]::Exists($_)}|Sort-Object -Unique -CaseSensitive);$before=@();foreach($path in $holdPaths){$before+=Get-FileBinding $path;$held+=[IO.FileStream]::new($path,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read)}
        $heldWriteRejected=$false
        try {
            $writeProbe=[IO.FileStream]::new($holdPaths[0],[IO.FileMode]::Open,[IO.FileAccess]::Write,[IO.FileShare]::Read)
            $writeProbe.Dispose()
        } catch [IO.IOException] {
            $heldWriteRejected=$true
        }
        if(-not $heldWriteRejected){throw 'HELD_INPUT_WRITE_FALSE_PASS'}
        $rawTree=Get-R24RawCommitTree $SourceCommit;$manifest=[Collections.Generic.List[object]]::new();foreach($item in $rawTree.items){if(-not(validate_path_for_runner $item.path)){throw "MATERIALIZATION_PATH:$($item.path)"};$destination=Join-Path $materialRoot $item.path;$parentDir=[IO.Path]::GetDirectoryName($destination);if(-not[IO.Directory]::Exists($parentDir)){[IO.Directory]::CreateDirectory($parentDir)|Out-Null};$stream=[IO.FileStream]::new($destination,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None,4096,[IO.FileOptions]::WriteThrough);try{$stream.Write($item.bytes,0,$item.bytes.Length);$stream.Flush($true)}finally{$stream.Dispose()};if((Get-FileSha256 $destination)-cne$item.sha256){throw "MATERIALIZATION_DIGEST:$($item.path)"};$manifest.Add([ordered]@{path=$item.path;mode=$item.mode;object_id=$item.object_id;byte_count=$item.byte_count;sha256=$item.sha256})}
        $targetProbe=Join-Path $targetRoot 'target-probe.bin';$probeBytes=[byte[]](0x52,0x32,0x34);$stream=[IO.FileStream]::new($targetProbe,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None,4096,[IO.FileOptions]::WriteThrough);try{$stream.Write($probeBytes,0,$probeBytes.Length);$stream.Flush($true)}finally{$stream.Dispose()}
        $observedMaterial=Wait-Event -SourceIdentifier $watchers[3].created -Timeout 5;if($null-eq$observedMaterial){throw 'FIVE_ROOT_MATERIALIZATION_EVENT_MISSING'}
        foreach($watch in $watchers){foreach($queued in @(Get-Event -SourceIdentifier $watch.created -ErrorAction SilentlyContinue)){if($null-ne$queued.SourceEventArgs){$raw=$queued.SourceEventArgs.Name;$full=Join-Path $roots[$watch.name] $raw;$count=if([IO.File]::Exists($full)){[uint64](Get-Item -LiteralPath $full).Length}else{$null};$digest=if([IO.File]::Exists($full)){Get-FileSha256 $full}else{$null};$events.Add([ordered]@{sequence=$sequence;source=$watch.name;action='create';raw_path=$raw;byte_count=$count;content_sha256=$digest});$sequence++};Remove-Event -EventIdentifier $queued.EventIdentifier};foreach($queued in @(Get-Event -SourceIdentifier $watch.error -ErrorAction SilentlyContinue)){$events.Add([ordered]@{sequence=$sequence;source=$watch.name;action='overflow';raw_path=$null;byte_count=$null;content_sha256=$null});$sequence++;Remove-Event -EventIdentifier $queued.EventIdentifier}}
        $after=@($holdPaths|ForEach-Object{Get-FileBinding $_});if((ConvertTo-CanonicalJson $before)-cne(ConvertTo-CanonicalJson $after)){throw 'HELD_INPUT_MUTATION'}
        $generatedObservation=Invoke-R24GitRun (@('git','-C',$RepoRoot)+$GitSemanticConfig+@('status','--porcelain=v2','-z','--untracked-files=all','--','context/waves/2026-07-28-bastion-foundation/evidence/wp-tst-001')) $RepoRoot;$generatedPathsClean=$generatedObservation.native_exit_u32-eq0-and$generatedObservation.stdout_byte_count-eq0
        foreach($watch in $watchers){$watch.watcher.EnableRaisingEvents=$false;$events.Add([ordered]@{sequence=$sequence;source=$watch.name;action='watch-stop';raw_path=$null;byte_count=$null;content_sha256=$null});$sequence++}
        Assert-R24FiveRootEvents @($events);$manifestDigest=Get-TextSha256 (($manifest|ForEach-Object{(ConvertTo-CanonicalJson $_)+"`n"})-join'');$eventDigest=Get-TextSha256 (($events|ForEach-Object{(ConvertTo-CanonicalJson $_)+"`n"})-join'')
        [ordered]@{schema='test-gate-five-root-custody-dry-run.v1';source_commit=$SourceCommit;binding_status=if($SourceCommit-ceq$EntryCommit){'fixture-entry-pending-implementation'}else{'final-implementation'};roots=$roots;held_input_count=$held.Count;held_write_rejected=$heldWriteRejected;pre_snapshot_digest=Get-TextSha256 (ConvertTo-CanonicalJson $before);post_snapshot_digest=Get-TextSha256 (ConvertTo-CanonicalJson $after);generated_paths_clean=$generatedPathsClean;materialization_invocation_count=$rawTree.invocation_count;tree_item_count=$manifest.Count;tree_manifest_digest=$manifestDigest;event_count=$events.Count;event_digest=$eventDigest;events=@($events);status='passed'}
    } finally {
        foreach($handle in $held){$handle.Dispose()};foreach($watch in $watchers){$watch.watcher.EnableRaisingEvents=$false;$watch.watcher.Dispose();Unregister-Event -SourceIdentifier $watch.created -ErrorAction SilentlyContinue;Unregister-Event -SourceIdentifier $watch.error -ErrorAction SilentlyContinue};foreach($subscription in $subscriptions){$subscription|Remove-Job -Force -ErrorAction SilentlyContinue}
    }
}

function Invoke-R24FiveRootMaterializationForCommit([string]$Parent,[string]$SourceCommit) {
