    if($RawPath-is[string]){return $RawPath};Assert-ExactKeys $RawPath @('encoding','content','decoded_byte_count','decoded_sha256') 'RawGitPath';if($RawPath.encoding-cne'base64'){throw 'RAW_GIT_PATH_ENCODING'};try{$bytes=[Convert]::FromBase64String($RawPath.content)}catch{throw 'RAW_GIT_PATH_BASE64'};if([uint64]$bytes.Length-ne[uint64]$RawPath.decoded_byte_count-or(Get-BytesSha256 $bytes)-cne$RawPath.decoded_sha256){throw 'RAW_GIT_PATH_DIGEST'};[Text.UTF8Encoding]::new($false,$true).GetString($bytes)
