function Start-R24FiveRootCustodySession([string]$Parent,$ObservedPreflight) {
    $materialRoot=New-ExternalDirectory 'gapless-materialization' $Parent;$targetRoot=New-ExternalDirectory 'gapless-target' $Parent;$inputs=$ObservedPreflight.repository_inputs
    $roots=[ordered]@{worktree=[IO.Path]::GetFullPath($inputs.repo_root);'worktree-git'=[IO.Path]::GetFullPath($inputs.git_dir);'common-git'=[IO.Path]::GetFullPath($inputs.common_dir);materialization=$materialRoot;'cargo-target'=$targetRoot}
    $session=[ordered]@{roots=$roots;native_watcher=$null;native_lifecycle=@();pending_rename=$null;events=[Collections.Generic.List[object]]::new();sequence=[uint64]0;held=[Collections.Generic.List[IDisposable]]::new();held_rows=[Collections.Generic.List[object]]::new();delivery_barrier_complete=$false;stopped=$false;watch_frozen=$false;publication_filter_transitioned=$false}
    try {
        $rootNames=[string[]]@($roots.Keys);$rootPaths=[string[]]@($roots.Values);$session.native_watcher=[BastionTestGateV2.NativeFiveRootWatch]::new($rootNames,$rootPaths);foreach($name in $rootNames){Add-R24CustodyEvent $session $name 'watch-start' $null $null $null}
        $paths=@($ImplementationPaths|ForEach-Object{Join-Path $roots.worktree $_})+@((Join-Path $roots.worktree 'docs/vtrace/WP_TST_001.md'),(Join-Path $roots.worktree 'context/waves/2026-07-28-bastion-foundation/pulses/pulse-44-wp-tst-001-r24-corrective-lineage-candidate.md'),(Join-Path $roots.worktree 'context/waves/2026-07-28-bastion-foundation/pulses/pulse-45-wp-tst-001-r24-acceptance.md'),(Join-Path $roots.worktree 'context/waves/2026-07-28-bastion-foundation/pulses/pulse-46-wp-tst-001-r24-corrective-entry.md'),$inputs.index_path)+@($inputs.common_inputs_before|Where-Object state -eq 'present'|ForEach-Object absolute_path)
        foreach($path in @($paths|Where-Object{[IO.File]::Exists($_)}|Sort-Object -Unique -CaseSensitive)){$binding=Get-FileBinding $path;$handle=[IO.FileStream]::new($path,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);$session.held.Add($handle);$session.held_rows.Add([ordered]@{path=[IO.Path]::GetFullPath($path);byte_count=$binding.byte_count;sha256=$binding.sha256;access='read';share='read'})}
        $session
    } catch {Stop-R24FiveRootCustodySession $session -Abort -ErrorAction SilentlyContinue|Out-Null;throw}
}

function Drain-R24FiveRootCustodySession($Session,[AllowNull()][string]$FinalizationSelfPath=$null,[AllowNull()][object[]]$NativeRows=$null) {
    if($null-eq$NativeRows){if($Session.watch_frozen){throw 'WATCH_DRAIN_AFTER_FREEZE'};$NativeRows=@($Session.native_watcher.Drain(25))}
    $utf16=[Text.UnicodeEncoding]::new($false,$false,$true);$utf8=[Text.UTF8Encoding]::new($false,$true)
    foreach($row in @($NativeRows)){
        if($row.Action-eq0){Add-R24CustodyEvent $Session $row.Root 'overflow' $null $null $null;continue}
        $minimumRequest=if($Session.publication_filter_transitioned){[uint64]6}else{[uint64]1};$maximumRequest=if($Session.publication_filter_transitioned){[uint64]10}else{[uint64]5};$knownRoot=$null-ne$row.Root-and$Session.roots.Contains($row.Root)
        if($row.Action-lt1-or$row.Action-gt5-or$null-eq$row.RelativeUtf16-or-not$knownRoot-or$row.RequestId-lt$minimumRequest-or$row.RequestId-gt$maximumRequest-or$row.ExpectedKey-ne$row.ObservedKey-or$row.ExpectedOverlapped-ne$row.ObservedOverlapped-or-not$row.Success-or$row.Error-ne0-or$row.Phase-notin@('normal','shutdown')){throw "WATCH_NATIVE_ACTION:action=$($row.Action):root=$($row.Root):request=$($row.RequestId):expected_request=$minimumRequest..$maximumRequest`:expected_key=$($row.ExpectedKey):observed_key=$($row.ObservedKey):expected_overlapped=$($row.ExpectedOverlapped):observed_overlapped=$($row.ObservedOverlapped):success=$($row.Success):error=$($row.Error):phase=$($row.Phase)"}
        try{$relative=$utf16.GetString([byte[]]$row.RelativeUtf16);$rawPath=New-R24RawGitPath ($utf8.GetBytes($relative))}catch{throw 'WATCH_NATIVE_PATH_ENCODING'}
        $action=@{1='create';2='delete';3='write';4='rename-from';5='rename-to'}[[int]$row.Action];$count=$null;$digest=$null;$full=Join-Path $Session.roots[$row.Root] $relative
        if($action-ceq'rename-from'){if($null-ne$Session.pending_rename){throw 'WATCH_RENAME_ADJACENCY'};$Session.pending_rename=[ordered]@{root=$row.Root;request_id=$row.RequestId}}elseif($action-ceq'rename-to'){if($null-eq$Session.pending_rename-or$Session.pending_rename.root-cne$row.Root-or$Session.pending_rename.request_id-ne$row.RequestId){throw 'WATCH_RENAME_PAIR'};$Session.pending_rename=$null}elseif($null-ne$Session.pending_rename){throw 'WATCH_RENAME_ADJACENCY'}
        if($action-in@('create','write','rename-to')-and[IO.File]::Exists($full)){
            $canonicalFull=[IO.Path]::GetFullPath($full);$held=@($Session.held_rows|Where-Object{$_.path-ceq$canonicalFull}|Select-Object -Last 1)
            if($held.Count-eq1){$count=[uint64]$held[0].byte_count;$digest=$held[0].sha256}else{$count=[uint64](Get-Item -LiteralPath $full).Length;if([string]::IsNullOrEmpty($FinalizationSelfPath) -or -not ($canonicalFull.Equals([IO.Path]::GetFullPath($FinalizationSelfPath),[StringComparison]::OrdinalIgnoreCase))){$digest=Get-FileSha256 $full}}
            if(-not[string]::IsNullOrEmpty($FinalizationSelfPath)-and$canonicalFull.Equals([IO.Path]::GetFullPath($FinalizationSelfPath),[StringComparison]::OrdinalIgnoreCase)){$digest=$null}
        }
        Add-R24CustodyEvent $Session $row.Root $action $rawPath $count $digest
    }
    if(@($Session.events|Where-Object action -eq 'overflow').Count-ne0){throw 'WATCH_OVERFLOW'}
}

function Set-R24PublicationWatchMode($Session) {if($Session.publication_filter_transitioned){return};$rows=@($Session.native_watcher.TransitionAllToNameOnly());if($rows.Count-ne0){throw 'WATCH_HANDOFF_NOT_QUIESCENT'};Drain-R24FiveRootCustodySession $Session $null $rows;$Session.publication_filter_transitioned=$true}

function Add-R24MaterializedHeldInputs($Session) {
    foreach($file in @(Get-ChildItem -LiteralPath $Session.roots.materialization -File -Recurse|Sort-Object FullName -CaseSensitive)){$binding=Get-FileBinding $file.FullName;$handle=[IO.FileStream]::new($file.FullName,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);$Session.held.Add($handle);$Session.held_rows.Add([ordered]@{path=$file.FullName;byte_count=$binding.byte_count;sha256=$binding.sha256;access='read';share='read'})}
}

function Stop-R24FiveRootCustodySession($Session,[switch]$Abort) {
    if($null-eq$Session-or$Session.stopped){return};if(-not$Abort-and$Session.Contains('repository_publication_authorized')-and$Session.repository_publication_authorized-and-not$Session.delivery_barrier_complete){throw 'WATCH_DELIVERY_BARRIER_REQUIRED'}
    if($Abort){if($null-ne$Session.native_watcher){$Session.native_watcher.Dispose()}}else{Drain-R24FiveRootCustodySession $Session;$terminal=@($Session.native_watcher.FreezeAndClose());$Session.watch_frozen=$true;Drain-R24FiveRootCustodySession $Session $null $terminal;if($null-ne$Session.pending_rename){throw 'WATCH_RENAME_UNPAIRED'};$Session.native_lifecycle=@($Session.native_watcher.Lifecycle);for($i=0;$i-lt$Session.native_lifecycle.Count;$i++){if($Session.native_lifecycle[$i].Sequence-ne$i){throw 'WATCH_LIFECYCLE_SEQUENCE'}};$ops=@($Session.native_lifecycle.Operation);if(@($ops|Where-Object{$_-ceq'cancel'}).Count-ne5-or@($ops|Where-Object{$_-ceq'root-close'}).Count-ne5-or@($ops|Where-Object{$_-ceq'completion-shutdown'}).Count-ne5-or@($ops|Where-Object{$_-ceq'buffer-zero-free'}).Count-ne5-or@($ops|Where-Object{$_-ceq'overlapped-zero-free'}).Count-ne5-or@($ops|Where-Object{$_-ceq'iocp-close'}).Count-ne1){throw 'WATCH_LIFECYCLE_CARDINALITY'};$freeze=[array]::IndexOf($ops,'issuance-freeze');$cancel=[array]::IndexOf($ops,'cancel');$terminalDrain=[array]::IndexOf($ops,'terminal-drain');$free=[array]::IndexOf($ops,'buffer-zero-free');$portClose=[array]::IndexOf($ops,'iocp-close');if($freeze-lt0-or$freeze-ge$cancel-or$terminalDrain-le$cancel-or$free-le$terminalDrain-or$portClose-le$free){throw 'WATCH_LIFECYCLE_ORDER'};Add-R24CustodyEvent $Session 'worktree' 'watch-stop' $null $null $null}
    $Session.stopped=$true;foreach($handle in $Session.held){$handle.Dispose()}
    if(-not$Abort){$repositoryMutations=@($Session.events|Where-Object{$_.source-in@('worktree','worktree-git','common-git')-and$_.action-notin@('watch-start','watch-stop')});if($repositoryMutations.Count-ne0){if(-not$Session.Contains('repository_publication_authorized')-or-not$Session.repository_publication_authorized){throw 'WATCH_REPOSITORY_MUTATION'};foreach($event in $repositoryMutations){$path=ConvertFrom-R24RawGitPath $event.raw_path;if($event.source-cne'worktree'-or$event.action-notin@('create','write')-or$path-notin$Session.repository_publication_paths){throw 'WATCH_UNAUTHORIZED_REPOSITORY_MUTATION'}}};$Session.event_digest=Get-TextSha256 (($Session.events|ForEach-Object{(ConvertTo-CanonicalJson $_)+"`n"})-join'');$Session.denied_handle_set_digest=Get-TextSha256 (($Session.held_rows|Sort-Object path -CaseSensitive|ForEach-Object{(ConvertTo-CanonicalJson $_)+"`n"})-join'');$Session.native_lifecycle_digest=Get-TextSha256 (($Session.native_lifecycle|ForEach-Object{(ConvertTo-CanonicalJson $_)+"`n"})-join'')}
    $Session
}

