function New-R24LiveCustodySnapshot([string]$Stage,$Session,$ObservedPreflight,[string]$ImplementationTree,[AllowNull()][string]$MaterialManifestDigest,[AllowNull()]$SelfProjection=$null) {
    if($Stage-notin@('pre-materialization','post-materialization','post-worker','post-evidence','post-receipt','post-finalization')){throw 'CUSTODY_SNAPSHOT_STAGE'};$prefix=Get-R24CustodyPrefix $Session;$fresh=if(-not[string]::IsNullOrWhiteSpace($ImplementationCommit)){(Get-ObservedPreflight $RepoRoot $ImplementationCommit).preflight}else{$ObservedPreflight};if($fresh.status-cne'pass'){throw "CUSTODY_FRESH_REREAD:$Stage"};$worktreeDigest=Get-TextSha256 ((@($fresh.git_observations|Where-Object{$_.command_id-like'porcelain_state_*'})|ForEach-Object{(ConvertTo-CanonicalJson $_)+"`n"})-join'')
    New-DigestedObject ([ordered]@{stage=$Stage;git_observations=$fresh.git_observations;repository_inputs=$fresh.repository_inputs;generated_paths=$fresh.generated_paths;self_projection=$SelfProjection;implementation_tree_digest=$ImplementationTree;material_manifest_digest=$MaterialManifestDigest;worktree_digest=$worktreeDigest;watch_event_count=$prefix.count;watch_event_digest=$prefix.digest}) 'snapshot_digest'
}

