function Complete-R24CustodyDeliveryBarrier($Session,$FreshPreflight,[string]$FinalizationPath,[uint64]$ExpectedByteCount,$PlannedEvidence) {
    $deadline=[DateTime]::UtcNow.AddSeconds(10);$events=@();do{Drain-R24FiveRootCustodySession $Session $FinalizationPath @($Session.native_watcher.Drain(100));$events=@($Session.events|Where-Object{$_.source-ceq'worktree'-and$_.action-ceq'create'-and$null-ne$_.raw_path-and(ConvertFrom-R24RawGitPath $_.raw_path)-ceq$FinalizationPath});if($events.Count-eq1){break};if($events.Count-gt1){throw 'WATCH_DELIVERY_BARRIER_EVENT_CARDINALITY'};if([DateTime]::UtcNow-ge$deadline){throw 'WATCH_DELIVERY_BARRIER_ACK_TIMEOUT'}}while($true)
    $inventory=@($FreshPreflight.generated_paths.items|Where-Object{$_.path-ceq$FinalizationPath});if($inventory.Count-ne1-or[uint64]$inventory[0].byte_count-ne$ExpectedByteCount-or$inventory[0].sha256-cnotmatch'^[0-9a-f]{64}$'){throw 'WATCH_DELIVERY_BARRIER_INVENTORY'};Assert-R24AcknowledgedFinalizationEvents @($Session.events) $FinalizationPath $ExpectedByteCount;Assert-R24CompleteGeneratedClosure $FreshPreflight.generated_paths @($PlannedEvidence);$Session.delivery_barrier_ack=[ordered]@{source='worktree';action='create';path=$FinalizationPath;sequence=$events[0].sequence;byte_count=$ExpectedByteCount};$Session.delivery_barrier_complete=$true
}

function Assert-R24CompleteGeneratedClosure($GeneratedPaths,[object[]]$SupervisorPlannedArtifacts=@()) {
    foreach($item in $GeneratedPaths.items){if($item.path-cmatch'^context/waves/2026-07-28-bastion-foundation/evidence/wp-tst-001/runs/.+/EVID-WP-TST-001-(.+)-v[0-9]{4}[.]json$'){$planned=@($SupervisorPlannedArtifacts|Where-Object{$_.evidence_path-ceq$item.path});if($planned.Count-gt1){throw 'GENERATED_MODE_SUPERVISOR_PLAN_CARDINALITY'};if($planned.Count-eq1){Assert-R24GeneratedArtifactAddition $item $planned[0]};$evidence=Read-StrictJson (Join-Path $RepoRoot $item.path) 'test-gate-evidence.v17';Assert-R24ModeEvidenceEnvelope $evidence;Assert-R24ModeArtifactHistory $evidence $RepoRoot}elseif($item.path-cmatch'^context/waves/2026-07-28-bastion-foundation/evidence/wp-tst-001/sets/EVID-WP-TST-001-SET-v[0-9]{4}[.]json$'){$planned=@($SupervisorPlannedArtifacts|Where-Object{$_.set_path-ceq$item.path});if($planned.Count-gt1){throw 'GENERATED_SET_SUPERVISOR_PLAN_CARDINALITY'};if($planned.Count-eq1){Assert-R24GeneratedArtifactAddition $item $planned[0]};$set=Read-StrictJson (Join-Path $RepoRoot $item.path) 'test-gate-evidence-set.v16';Assert-R24EvidenceSet $set $RepoRoot}}
}

function Assert-R24AcknowledgedFinalizationEvents([object[]]$Events,[string]$FinalizationPath,[uint64]$ExpectedByteCount) {
    $create=@($Events|Where-Object{$_.source-ceq'worktree'-and$_.action-ceq'create'-and$null-ne$_.raw_path-and(ConvertFrom-R24RawGitPath $_.raw_path)-ceq$FinalizationPath});if($create.Count-ne1-or[uint64]$create[0].byte_count-ne$ExpectedByteCount-or$null-ne$create[0].content_sha256){throw 'WATCH_DELIVERY_BARRIER_EVENT'};$extra=@($Events|Where-Object{$_.source-ceq'worktree'-and$_.action-in@('write','rename-from','rename-to','delete')-and$null-ne$_.raw_path-and(ConvertFrom-R24RawGitPath $_.raw_path)-ceq$FinalizationPath});if($extra.Count-ne0){if(@($extra|Where-Object sequence -gt $create[0].sequence).Count){throw 'WATCH_DELAYED_EVENT_AFTER_ACK'};throw 'WATCH_DELIVERY_BARRIER_EXTRA_EVENT'}
}

function Complete-R24SetDeliveryBarrier($Session,$FreshPreflight,[string[]]$ExpectedPaths,[object[]]$SupervisorPlannedSets) {
    $deadline=[DateTime]::UtcNow.AddSeconds(10);do{Drain-R24FiveRootCustodySession $Session $null @($Session.native_watcher.Drain(100));$events=@($Session.events|Where-Object{$_.source-ceq'worktree'-and$_.action-ceq'create'-and$null-ne$_.raw_path-and(ConvertFrom-R24RawGitPath $_.raw_path)-in$ExpectedPaths});if($events.Count-eq$ExpectedPaths.Count){break};if($events.Count-gt$ExpectedPaths.Count){throw 'SET_WATCH_EVENT_CARDINALITY'};if([DateTime]::UtcNow-ge$deadline){throw 'SET_WATCH_ACK_TIMEOUT'}}while($true);$actual=@($events|ForEach-Object{ConvertFrom-R24RawGitPath $_.raw_path});if((ConvertTo-CanonicalJson $actual)-cne(ConvertTo-CanonicalJson $ExpectedPaths)-or@($events|Where-Object{$null-eq$_.content_sha256-or$_.byte_count-le0}).Count-ne0){throw 'SET_WATCH_CREATION_ORDER'};foreach($path in $ExpectedPaths){$item=@($FreshPreflight.generated_paths.items|Where-Object path -CEQ $path);if($item.Count-ne1){throw 'SET_WATCH_INVENTORY'}};Assert-R24CompleteGeneratedClosure $FreshPreflight.generated_paths $SupervisorPlannedSets;$Session.delivery_barrier_ack=[ordered]@{source='worktree';action='create-set-sequence';path=$ExpectedPaths[-1];sequence=$events[-1].sequence;byte_count=$events[-1].byte_count};$Session.delivery_barrier_complete=$true
}

function Materialize-R24CanonicalCommit($Session,[string]$Commit) {
