    foreach($item in $raw.items){$destination=Join-Path $Session.roots.materialization $item.path;$parent=[IO.Path]::GetDirectoryName($destination);if(-not[IO.Directory]::Exists($parent)){[IO.Directory]::CreateDirectory($parent)|Out-Null};$stream=[IO.FileStream]::new($destination,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None,4096,[IO.FileOptions]::WriteThrough);try{$stream.Write($item.bytes,0,$item.bytes.Length);$stream.Flush($true)}finally{$stream.Dispose()};if((Get-FileSha256 $destination)-cne$item.sha256){throw "MATERIALIZATION_DIGEST:$($item.path)"};$manifest.Add([ordered]@{path=New-R24RawGitPath ([Text.Encoding]::UTF8.GetBytes($item.path));mode=$item.mode;object_id=$item.object_id;byte_count=$item.byte_count;sha256=$item.sha256})}
    Drain-R24FiveRootCustodySession $Session;Add-R24MaterializedHeldInputs $Session;$digest=Get-TextSha256 (($manifest|ForEach-Object{(ConvertTo-CanonicalJson $_)+"`n"})-join'');[ordered]@{manifest=@($manifest);manifest_digest=$digest;invocation_count=$raw.invocation_count}
}

function Invoke-R24StartupLedgerDiscovery([string]$LedgerPhysicalRoot,[AllowNull()]$Session=$null,[AllowNull()][string]$PublicationRoot=$null,[AllowNull()][string]$LogicalLedgerRoot=$null) {
