    $attemptLeaf=[IO.Path]::GetFileName([IO.Path]::GetFullPath($LedgerPhysicalRoot).TrimEnd([IO.Path]::DirectorySeparatorChar));if($attemptLeaf-cnotmatch'^run-a([0-9]{5})$'-or[int]$Matches[1]-lt1){throw 'STARTUP_ATTEMPT_DIRECTORY'}
    $files=@(Get-ChildItem -LiteralPath $LedgerPhysicalRoot -File -Filter 'r*.json'|Sort-Object Name -CaseSensitive);if($files.Count-eq0){throw 'STARTUP_LEDGER_EMPTY_DIRECTORY'};$records=[Collections.Generic.List[object]]::new();$predecessor=$null
