    $writer=New-LedgerWriter $LedgerPhysicalRoot $records[0].mode ([int]$records[0].execution_evidence_version) ([int]$records[0].run_attempt) $records[0].execution_id $records[0].run_id $records[0].implementation_commit $records[0].lineage_binding $Session $PublicationRoot $LogicalLedgerRoot;for($i=0;$i-lt$records.Count;$i++){$suffix=[ordered]@{};foreach($key in @(Get-R24LedgerSuffixKeys $records[$i].record_kind $records[$i])){$suffix[$key]=$records[$i][$key]};Assert-R24LedgerRecordCandidate $writer $records[$i].record_kind $suffix;$writer.records.Add([ordered]@{filename=$files[$i].Name;path=$files[$i].FullName;record=$records[$i]});$writer.predecessor=$records[$i].record_digest;$writer.ordinal=$i+1;Update-R24LedgerWriterState $writer $records[$i].record_kind $records[$i]};if(-not$writer.run_started-or$writer.run_closed){throw 'STARTUP_RECOVERY_RUN_STATE'}
    $activeWorker=$null-ne$writer.open_target-or($null-ne$writer.open_phase-and$writer.open_phase.phase_kind-ceq'command');$rows=@();$terminationSummary=$null;$openResult='not-attempted';if($activeWorker){$retained=if($null-ne$writer.open_target){$writer.open_target}else{$writer.open_phase};foreach($field in @('process_id','process_creation_filetime','job_name','job_configuration_digest')){if($null-eq$retained[$field]){throw "STARTUP_WORKER_IDENTITY:$field"}};$recovery=[BastionTestGateV2.Job]::RecoverClosed($retained.job_name,[uint32]$retained.process_id,[uint64]$retained.process_creation_filetime,$JobMemoryBytes,$JobMemoryBytes);$partition=Convert-R24SupervisorEventPartition $recovery.NativeEvents 'startup-discovery';$rows=@($partition.native_api_events);$terminationSummary=[ordered]@{source='recovery';detail="job_name=$($retained.job_name);job_configuration_digest=$($retained.job_configuration_digest);process_id=$($retained.process_id);creation_filetime=$($retained.process_creation_filetime);stdout_sha256=null;stderr_sha256=null;observed_utc=$([DateTimeOffset]::UtcNow.ToString('O'))"};$openResult=$recovery.OpenResult;if($openResult-ceq'reopened-handle'){if(-not$recovery.IdentityMatch-or-not$recovery.ConfigurationMatch-or-not$recovery.TerminateSucceeded-or-not$recovery.JobEmpty){throw 'STARTUP_DISCOVERY_RECOVERY'}}elseif($openResult-ceq'not-found'){if($recovery.IdentityMatch-or$recovery.ConfigurationMatch-or-not$recovery.JobEmpty){throw 'STARTUP_DISCOVERY_ABSENT'}}else{throw 'STARTUP_DISCOVERY_STATE'}};$closedBinding=$null
    if($activeWorker){$probe=[ordered]@{native_api_events=$rows;termination_summary=$terminationSummary;native_exit_u32=if($openResult-ceq'not-found'){$null}else{$recovery.NativeExit};retained_start=[ordered]@{process_id=[uint32]$retained.process_id;process_creation_filetime=[uint64]$retained.process_creation_filetime;job_name=$retained.job_name;job_configuration_digest=$retained.job_configuration_digest}};$observation=New-R24TerminationObservation 'supervisor-loss' $probe $records[0].run_id $records[-1].record_digest}else{$observation=New-R24PreChildSupervisorLossObservation $records[0].run_id $records[-1].record_digest};$recoveryUtc=[DateTimeOffset]::UtcNow.ToString('O');if($null-ne$writer.open_target){$target=$writer.open_target;Add-LedgerRecord $writer ($target.record_kind.Replace('-start','-recovery')) ([ordered]@{phase_ordinal=$target.phase_ordinal;phase_id=$target.phase_id;target_ordinal=$target.target_ordinal;controlled_id=$target.controlled_id;assertion=$target.assertion;argv=$target.argv;paired_start_digest=$target.record_digest;termination_observation=$observation;native_exit_u32=$observation.native_exit_u32;portable_exit=$observation.portable_exit;state='failed';reason='supervisor-loss';stdout_sha256=$observation.stdout_sha256;stderr_sha256=$observation.stderr_sha256;recovery_utc=$recoveryUtc})|Out-Null};if($null-ne$writer.open_phase){$phase=$writer.open_phase;Add-LedgerRecord $writer ($phase.record_kind.Replace('-start','-recovery')) ([ordered]@{phase_ordinal=$phase.phase_ordinal;phase_id=$phase.phase_id;phase_kind=$phase.phase_kind;argv=$phase.argv;paired_start_digest=$phase.record_digest;termination_observation=$observation;native_exit_u32=$observation.native_exit_u32;portable_exit=$observation.portable_exit;state='failed';reason='supervisor-loss';recovery_utc=$recoveryUtc})|Out-Null};Add-LedgerRecord $writer 'run-recovery' ([ordered]@{paired_start_digest=$records[0].record_digest;termination_observation=$observation;native_exit_u32=$observation.nativ