function Invoke-R24StartupLedgerCutPointMatrix([string]$Parent,$JobProbe,[string]$Implementation) {
    $cases=[Collections.Generic.List[object]]::new();$argv=@('cargo','check');$newWriter={param([string]$Name,[int]$Attempt)$caseRoot=New-ExternalDirectory $Name $Parent;$root=Join-Path $caseRoot ('run-a{0:d5}'-f$Attempt);[IO.Directory]::CreateDirectory($root)|Out-Null;$writer=New-LedgerWriter $root 'L0Check' 1 $Attempt 'EXEC-WP-TST-001-L0Check-v0001' $JobProbe.run_id $Implementation;[ordered]@{name=$Name;root=$root;writer=$writer;run=Add-LedgerRecord $writer 'run-start' ([ordered]@{start_utc=[DateTimeOffset]::UtcNow.ToString('O')})}}
