    $command=&$newWriter 'startup-command-open' 31;$commandPhase=Add-LedgerRecord $command.writer 'phase-01-start' ([ordered]@{phase_ordinal=1;phase_id='PHASE-L0Check-01';phase_kind='command';argv=$JobProbe.argv;process_id=[uint32]$JobProbe.process_id;process_creation_filetime=[uint64]$JobProbe.process_creation_filetime;job_name=$JobProbe.job_name;job_configuration_digest=$JobProbe.job_configuration_digest;start_utc=[DateTimeOffset]::UtcNow.ToString('O')});&$closeCase $command @('phase-01-recovery','run-recovery') $true
