    $phase=&$newWriter 'startup-phase-paired' 33;$phaseStart=Add-LedgerRecord $phase.writer 'phase-01-start' ([ordered]@{phase_ordinal=1;phase_id='PHASE-L0Check-01';phase_kind='targets';argv=$argv;start_utc=[DateTimeOffset]::UtcNow.ToString('O')});Add-LedgerRecord $phase.writer 'phase-01-completion' ([ordered]@{phase_ordinal=1;phase_id='PHASE-L0Check-01';phase_kind='targets';argv=$argv;paired_start_digest=$phaseStart.record_digest;native_exit_u32=[uint32]0;portable_exit=0;state='passed';reason='all-children-passed';end_utc=[DateTimeOffset]::UtcNow.ToString('O')})|Out-Null;&$closeCase $phase @('run-recovery') $false
