function Invoke-R24StartupLedgerNegativeMatrix([string]$Parent,$JobProbe,[string]$Implementation) {
    $results=[Collections.Generic.List[object]]::new();$newWriter={param([string]$Name,[int]$Attempt)$caseRoot=New-ExternalDirectory $Name $Parent;$root=Join-Path $caseRoot ('run-a{0:d5}'-f$Attempt);[IO.Directory]::CreateDirectory($root)|Out-Null;$writer=New-LedgerWriter $root 'L0Check' 1 $Attempt 'EXEC-WP-TST-001-L0Check-v0001' $JobProbe.run_id $Implementation;[ordered]@{root=$root;writer=$writer;run=Add-LedgerRecord $writer 'run-start' ([ordered]@{start_utc=[DateTimeOffset]::UtcNow.ToString('O')})}};$reject={param([string]$Name,[scriptblock]$Action)$reason=$null;try{&$Action;throw "NEGATIVE_FALSE_PASS:$Name"}catch{if($_.Exception.Message-ceq"NEGATIVE_FALSE_PASS:$Name"){throw};$reason=$_.Exception.Message};$results.Add([ordered]@{case=$Name;rejected=$true;reason=$reason})};$rewrite={param([string]$Path,$Value)$bytes=[Text.Encoding]::UTF8.GetBytes((ConvertTo-CanonicalJson $Value)+"`n");[IO.File]::WriteAllBytes($Path,$bytes)}
