    if($Binding.source_kind-cne$(if($Scope-ceq'SET'){'set_evidence'}else{'mode_evidence'})-or$Binding.source_ref-cne$EvidenceId-or$Binding.source_digest-cne(Get-BytesSha256 $Bytes)-or$Binding.lineage_digest-cne$LineageDigest-or$Binding.author_id-cne'REV-TST-EVIDENCE-AUTHOR'-or$Binding.controller_id-cne'REV-TST-EVIDENCE-CONTROLLER'){throw 'EVIDENCE_CUSTODY_BINDING'}
    $dispatch=New-R24ValidatorDispatch 'evidence-custody' $ArtifactPath 'vtrace-evidence-custody.v6' $ParentPath $null;Assert-R24ValidatorDispatch $dispatch 'evidence-custody' $ArtifactPath 'vtrace-evidence-custody.v6' $ParentPath $null
}

function Invoke-R24EvidenceCustodyDispatchMatrix {
    $lineage='1'*64;$id='EVID-WP-TST-001-L0Check-v0001';$bytes=New-R24EvidenceCustodyBytes 'L0Check' $id $lineage;$binding=New-R24AuthorBinding 'mode_evidence' $id (Get-BytesSha256 $bytes) $lineage 'REV-TST-EVIDENCE-AUTHOR' 'REV-TST-EVIDENCE-CONTROLLER';Assert-R24EvidenceCustodyPreimage $bytes 'L0Check' $id $lineage $binding '/identity_registry/bindings/0/custody_preimage' '/identity_registry/bindings/0'
    $text=[Text.Encoding]::UTF8.GetString($bytes);$rows=$text.Split("`n");$missing=[Text.Encoding]::UTF8.GetBytes((@($rows[0..5]+$rows[7])+''-join"`n"));$swapped=@($rows);$temporary=$swapped[1];$swapped[1]=$swapped[2];$swapped[2]=$temporary;$reordered=[Text.Encoding]::UTF8.GetBytes(($swapped-join"`n"));$badBinding=[ordered]@{};foreach($key in $binding.Keys){$badBinding[$key]=$binding[$key]};$badBinding.source_digest='0'*64
