    foreach($case in @([ordered]@{name='wrong-mode';kind='mode';scope='L0Check';expected=$id;actual='EVID-WP-TST-001-L0Format-v0001';source='mode_evidence'},[ordered]@{name='wrong-origin-version';kind='mode';scope='L0Check';expected=$id;actual='EVID-WP-TST-001-L0Check-v0002';source='mode_evidence'},[ordered]@{name='wrong-set-version';kind='set';scope='SET';expected='EVID-WP-TST-001-SET-v0001';actual='EVID-WP-TST-001-SET-v0002';source='set_evidence'})){$actualBytes=New-R24EvidenceCustodyBytes $(if($case.source-ceq'set_evidence'){'SET'}else{($case.actual-split'-')[-2]}) $case.actual $lineage;$actualBinding=New-R24AuthorBinding $case.source $case.actual (Get-BytesSha256 $actualBytes) $lineage 'REV-TST-EVIDENCE-AUTHOR' 'REV-TST-EVIDENCE-CONTROLLER';$actualRegistry=New-R24IdentityRegistry @($actualBinding);try{Assert-R24EnvelopeEvidenceCustodyBinding $actualRegistry $case.kind $case.scope $case.expected $lineage;throw "NEGATIVE_FALSE_PASS:$($case.name)"}catch{if($_.Exception.Message-ceq"NEGATIVE_FALSE_PASS:$($case.name)"){throw};$negative.Add($case.name)}}
