function New-R24IdentityRegistry([object[]]$Bindings) {
    $keys=@('schema','source_kind','source_ref','source_digest','wp_revision','lineage_digest','author_id','controller_id','binding_digest')
    foreach($binding in $Bindings){Assert-ExactKeys $binding $keys 'AuthorBindingV7';if($binding.schema-cne'vtrace-author-binding.v7'-or$binding.wp_revision-cne$WpRevision){throw 'AUTHOR_BINDING_VERSION'};Assert-SelfDigest $binding 'binding_digest'}
    $ordered=@($Bindings|Sort-Object @{Expression={"$($_.source_kind)`t$($_.source_ref)"}} -CaseSensitive)
    $identity=@($ordered|ForEach-Object{"$($_.source_kind)`t$($_.source_ref)"})
    if(@($identity|Sort-Object -Unique -CaseSensitive).Count-ne$identity.Count){throw 'AUTHOR_BINDING_DUPLICATE'}
    $positive=@($ordered|Where-Object source_kind -ne 'failed_r14_implementation')
    $failed=@($ordered|Where-Object source_kind -eq 'failed_r14_implementation')
    $candidate=@($positive|ForEach-Object{$_.author_id;$_.controller_id}|Sort-Object -Unique -CaseSensitive)
    $failedIds=@($failed|ForEach-Object{$_.author_id;$_.controller_id}|Sort-Object -Unique -CaseSensitive)
    New-DigestedObject ([ordered]@{schema='vtrace-identity-registry.v7';bindings=$ordered;candidate_author_ids=$candidate;failed_author_ids=$failedIds}) 'registry_digest'
}

function Assert-R24IdentityRegistry($Registry) {
