    Assert-SelfDigest $Registry 'registry_digest'
    $rebuilt=New-R24IdentityRegistry @($Registry.bindings)
    if((ConvertTo-CanonicalJson $rebuilt)-cne(ConvertTo-CanonicalJson $Registry)){throw 'IDENTITY_REGISTRY_PROJECTION'}
    for($index=0;$index-lt$Registry.bindings.Count;$index++){$binding=$Registry.bindings[$index];if($binding.source_kind-in@('mode_evidence','set_evidence')){$scope=if($binding.source_kind-ceq'set_evidence'){'SET'}elseif($binding.source_ref-cmatch'^EVID-WP-TST-001-(.+)-v[0-9]{4}$'){$Matches[1]}else{throw 'EVIDENCE_CUSTODY_MODE_REF'};$parent="/identity_registry/bindings/$index";$path="$parent/custody_preimage";$bytes=New-R24EvidenceCustodyBytes $scope $binding.source_ref $binding.lineage_digest;Assert-R24EvidenceCustodyPreimage $bytes $scope $binding.source_ref $binding.lineage_digest $binding $path $parent}
    }
