      'defer'{Assert-ExactKeys $Item @('id','claim_digest','owner','destination','closure_condition','hold_behavior','closure') 'Defer';if($Item.id-cnotmatch"^DEF-$escaped-$lane-v([0-9]{4})-([0-9]{3})$"-or[int]$Matches[1]-lt1-or[int]$Matches[1]-gt$DecisionVersion-or$Item.claim_digest-cnotmatch'^[0-9a-f]{64}$'-or$Item.owner-cnotmatch'^REV-[A-Z0-9][A-Z0-9-]{0,59}$'-or$Item.destination-notin$ReviewLanes-or$Item.closure_condition-cnotmatch'^[A-Za-z0-9][A-Za-z0-9 ._:-]{0,127}$'-or$Item.hold_behavior-cne'block-promotion'-or$Item.closure-notin@('open','remediated')){throw 'DEFER_SHAPE'}}
      'dissent'{Assert-ExactKeys $Item @('id','lane','claim_digest','record_digest','disposition') 'Dissent';if($Item.id-cnotmatch"^DIS-$escaped-$lane-v([0-9]{4})-([0-9]{3})$"-or[int]$Matches[1]-lt1-or[int]$Matches[1]-gt$DecisionVersion-or$Item.lane-cne$ReviewLanes[$LaneIndex]-or$Item.claim_digest-cnotmatch'^[0-9a-f]{64}$'-or$Item.record_digest-cnotmatch'^[0-9a-f]{64}$'-or$Item.disposition-notin@('open','retained','resolved')){throw 'DISSENT_SHAPE'}}
      'conflict'{Assert-ExactKeys $Item @('id','lane','left_digest','right_digest','owner','disposition') 'Conflict';if($Item.id-cnotmatch"^CON-$escaped-$lane-v([0-9]{4})-([0-9]{3})$"-or[int]$Matches[1]-lt1-or[int]$Matches[1]-gt$DecisionVersion-or$Item.lane-cne$ReviewLanes[$LaneIndex]-or$Item.left_digest-cnotmatch'^[0-9a-f]{64}$'-or$Item.right_digest-cnotmatch'^[0-9a-f]{64}$'-or$Item.left_digest-ceq$Item.right_digest-or$Item.owner-cnotmatch'^REV-[A-Z0-9][A-Z0-9-]{0,59}$'-or$Item.disposition-notin@('open','retained','resolved')){throw 'CONFLICT_SHAPE'}}
