function Assert-R24FixtureDecision($Decision,[string]$Scope,[int]$LaneIndex,[AllowNull()]$Prior) {
    Assert-ExactKeys $Decision @('schema','wp_revision','lineage_binding_digest','decision_id','decision_version','predecessor_decision_id','predecessor_decision_digest','predecessor_decision_version','lane','status','reviewer_id','reviewer_authentication_digest','independence','assurance','findings','defer','dissent','conflicts','closure','decision_record_digest') 'DecisionV7';Assert-SelfDigest $Decision 'decision_record_digest'
    if($Decision.schema-cne'test-gate-decision.v7'-or$Decision.wp_revision-cne$WpRevision-or$Decision.lane-cne$ReviewLanes[$LaneIndex]-or$Decision.decision_id-cne('DEC-WP-TST-001-{0}-L{1:d2}-v{2:d4}'-f$Scope,$LaneIndex,$Decision.decision_version)-or$Decision.independence-notin@('independent','conflicted')-or($LaneIndex-in@(0,1)-and$Decision.assurance-notin@('pass','fail'))-or($LaneIndex-notin@(0,1)-and$Decision.assurance-cne'not-applicable')){throw 'DECISION_IDENTITY'}
    foreach($item in @($Decision.findings)){Assert-R24ReviewItem 'finding' $item $Scope $LaneIndex $Decision.decision_version};foreach($item in @($Decision.defer)){Assert-R24ReviewItem 'defer' $item $Scope $LaneIndex $Decision.decision_version};foreach($item in @($Decision.dissent)){Assert-R24ReviewItem 'dissent' $item $Scope $LaneIndex $Decision.decision_version};foreach($item in @($Decision.conflicts)){Assert-R24ReviewItem 'conflict' $item $Scope $LaneIndex $Decision.decision_version}
    foreach($field in @('findings','defer','dissent','conflicts')){$ids=@($Decision[$field]|ForEach-Object id);if(($ids-join"`n")-cne(@($ids|Sort-Object -CaseSensitive)-join"`n")-or@($ids|Sort-Object -Unique -CaseSensitive).Count-ne$ids.Count){throw 'DECISION_ITEM_ORDER'}}
    $owners=@($Decision.findings|ForEach-Object owner)+@($Decision.defer|ForEach-Object owner)+$(if($Decision.independence-ceq'independent'){@($Decision.conflicts|ForEach-Object owner)}else{@()});if($Decision.reviewer_id-in$owners){throw 'DECISION_OWNER_INDEPENDENCE'}
    $openMaterialFindings=@($Decision.findings|Where-Object{$_.closure-ceq'open'-and$_.severity-in@('critical','major')});if(($Decision.assurance-ceq'fail')-and$openMaterialFindings.Count-eq0){throw 'DECISION_ASSURANCE_FINDING_BINDING'}
    $openDefer=@($Decision.defer|Where-Object{$_.closure-ceq'open'}).Count-ne0-or@($Decision.dissent|Where-Object{$_.disposition-in@('open','retained')}).Count-ne0-or@($Decision.conflicts|Where-Object{$_.disposition-in@('open','retained')}).Count-ne0;$openFinding=@($Decision.findings|Where-Object{$_.closure-ceq'open'}).Count-ne0;$expectedStatus=if($openDefer){'defer'}elseif($openFinding-or$Decision.assurance-ceq'fail'){'finding'}else{'pass'}
    if($null-ne$Prior){Assert-R24DecisionTransition $Prior $Decision $Scope $LaneIndex;$priorOpen=@($Prior.findings|Where-Object{$_.closure-ceq'open'}).Count+@($Prior.defer|Where-Object{$_.closure-ceq'open'}).Count+@($Prior.dissent|Where-Object{$_.disposition-in@('open','retained')}).Count+@($Prior.conflicts|Where-Object{$_.disposition-in@('open','retained')}).Count;$expectedClosure=if($expectedStatus-cne'pass'){'open'}elseif($priorOpen-gt0){'remediated'}else{'not-applicable'}}else{if($Decision.decision_version-ne1-or$null-ne$Decision.predecessor_decision_id-or$null-ne$Decision.predecessor_decision_digest-or$Decision.predecessor_decision_version-ne0){throw 'DECISION_ORIGIN'};foreach($kind in @('finding','defer','dissent','conflict')){$field=if($kind-ceq'finding'){'findings'}elseif($kind-ceq'defer'){'defer'}elseif($kind-ceq'dissent'){'dissent'}else{'conflicts'};Assert-R24ReviewArrayTransition $kind @() @($Decision[$field]) $Scope $LaneIndex 1};$expectedClosure=if($expectedStatus-cne'pass'){'open'}else{'not-applicable'}}
    if($Decision.status-cne$expectedStatus-or$Decision.closure-cne$expectedClosure){throw 'DECISION_DERIVATION'}
}

function Assert-R24DecisionAdmission($Decision,[string]$Scope,[int]$LaneIndex,$Authentication,[AllowNull()]$Prior,$Registry) {
    Assert-R24ReviewAuthentication $Authentication $LaneIndex $Decision.lineage_binding_digest $Registry;Assert-R24FixtureDecision $Decision $Scope $LaneIndex $Prior
    if($Decision.reviewer_id-cne$Authentication.reviewer_id-or$Decision.reviewer_authentication_digest-cne$Authentication.record_digest){throw 'DECISION_AUTHORITY'};$collision=$Decision.reviewer_id-in$Registry.candidate_author_ids;$expectedIndependence=if($collision){'conflicted'}else{'independent'};if($Decision.independence-cne$expectedIndependence){throw 'DECISION_INDEPENDENCE_DERIVATION'};$collisionConflicts=@($Decision.conflicts|Where-Object{$_.owner-ceq$Decision.reviewer_id-and$_.left_digest-ceq$Authentication.record_digest-and$_.right_digest-ceq$Registry.registry_digest-and$_.disposition-in@('open','retained')});if(($collision-and$collisionConflicts.Count-ne1)-or(-not$collision-and$collisionConflicts.Count-ne0)){throw 'DECISION_COLLISION_CONFLICT'}
}

function Assert-R24PassDecision($Decision,[string]$Scope,[int]$LaneIndex,$Authentication,[AllowNull()]$Predecessor,$Registry) {
    Assert-R24DecisionAdmission $Decision $Scope $LaneIndex $Authentication $Predecessor $Registry
    $expectedVersion=if($null-eq$Predecessor){1}else{$Predecessor.decision_version+1};$expected=New-R24PassDecision $Scope $LaneIndex $expectedVersion $Authentication $Predecessor
    if((ConvertTo-CanonicalJson $Decision)-cne(ConvertTo-CanonicalJson $expected)-or$Decision.reviewer_id-in$Registry.candidate_author_ids){throw 'DECISION_BINDING'}
}

function Assert-R24DecisionWave([object[]]$Decisions,[string]$Scope,[object[]]$Authentications,$Registry) {
    if($Decisions.Count-ne22-or$Authentications.Count-ne22){throw 'DECISION_WAVE_CARDINALITY'}
    $reviewers=@();for($i=0;$i-lt22;$i++){Assert-R24DecisionAdmission $Decisions[$i] $Scope $i $Authentications[$i] $null $Registry;$reviewers+=$Decisions[$i].reviewer_id}
    if(@($reviewers|Sort-Object -Unique -CaseSensitive).Count-ne22){throw 'DECISION_REVIEWER_BIJECTION'}
}

function Test-R24ReviewItemTransition([string]$Kind,[string]$From,[string]$To) {
    switch($Kind){
      'finding'{return $To-in $(switch($From){'open-hold'{@('open-hold','remediated-accept')}'open-defer'{@('open-defer','remediated-accept')}'remediated-accept'{@('remediated-accept')}'not-applicable-accept'{@('not-applicable-accept')}default{@()}})}
      'defer'{return $To-in $(if($From-ceq'open'){@('open','remediated')}elseif($From-ceq'remediated'){@('remediated')}else{@()})}
      'dissent'{return $To-in $(switch($From){'open'{@('retained','resolved')}'retained'{@('retained','resolved')}'resolved'{@('resolved')}default{@()}})}
      'conflict'{return $To-in $(switch($From){'open'{@('retained','resolved')}'retained'{@('retained','resolved')}'resolved'{@('resolved')}default{@()}})}
      default{throw 'REVIEW_ITEM_KIND'}
    }
}

function Invoke-R24ReconciliationMatrix {
    $domains=[ordered]@{finding=@('open-hold','open-defer','remediated-accept','not-applicable-accept');defer=@('open','remediated');dissent=@('open','retained','resolved');conflict=@('open','retained','resolved')};$accepted=0;$rejected=0
    foreach($kind in $domains.Keys){foreach($from in $domains[$kind]){foreach($to in $domains[$kind]){if(Test-R24ReviewItemTransition $kind $from $to){$accepted++}else{$rejected++}}}}
    if($accepted-ne19-or$rejected-ne19){throw "RECONCILIATION_MATRIX_CARDINALITY:$($accepted):$($rejected)"}
    if(Test-R24ReviewItemTransition 'finding' 'remediated-accept' 'open-hold'){throw 'RECONCILIATION_REOPEN'}
    [ordered]@{schema='test-gate-reconciliation-matrix.v1';finding_pairs=16;defer_pairs=4;dissent_pairs=9;conflict_pairs=9;accepted_pairs=$accepted;rejected_pairs=$rejected;status='passed'}
}

