function New-R24GovernanceObservation([string]$CommandId,[string[]]$Argv) {
    $run=Invoke-R24GitRun $Argv $RepoRoot
    if($run.native_exit_u32-ne0-or$run.stderr_byte_count-ne0){throw "GOVERNANCE_OBSERVATION_COMMAND:$CommandId"}
    New-DigestedObject ([ordered]@{schema='test-gate-governance-git-observation.v1';command_id=$CommandId;argv=$Argv;native_exit_u32=$run.native_exit_u32;portable_exit=$run.portable_exit;stdout_byte_count=$run.stdout_byte_count;stdout_sha256=$run.stdout_sha256;stderr_byte_count=$run.stderr_byte_count;stderr_sha256=$run.stderr_sha256}) 'observation_digest'
}

function Get-R24GovernanceAggregatePreimage($Binding,[object[]]$Data) {
    $lines=[Collections.Generic.List[string]]::new()
    foreach($item in $Data){$lines.Add("observation`t$($Binding["$($item.prefix)_scoped"].observation_digest)");$lines.Add("observation`t$($Binding["$($item.prefix)_unscoped"].observation_digest)")}
    foreach($item in $Data){$lines.Add("commit`t$($item.prefix)`t$($Binding["$($item.prefix)_commit"])");foreach($path in @($Binding["$($item.prefix)_paths"])){$lines.Add("path`t$($item.prefix)`t$path")}}
    $lines.Add("dispatch`t$($Binding.dispatch_metadata_digest)");($lines|ForEach-Object{"$_`n"})-join''
}

function New-R24GovernanceDelta($Dispatch) {
    Assert-R24ValidatorDispatch $Dispatch 'governance-delta' '/lineage_binding/governance_delta' 'test-gate-governance-delta.v9' '/lineage_binding' $null
    $data=@(Get-R24GovernanceDeltaData);$fields=[ordered]@{schema='test-gate-governance-delta.v9'};$git=@('git','-C',$RepoRoot)+$GitSemanticConfig
    foreach($item in $data){
        $tail=@('diff','--raw','-z','--no-abbrev','--full-index','--no-ext-diff','--find-renames=100%');$scoped=$git+$tail+@('--diff-filter=AMDR',$item.base,$item.commit,'--')+@($item.paths);$unscoped=$git+$tail+@($item.base,$item.commit)
        $scopedObservation=New-R24GovernanceObservation $item.command $scoped;$unscopedObservation=New-R24GovernanceObservation "$($item.command)_unscoped" $unscoped
        if($scopedObservation.stdout_byte_count-ne$unscopedObservation.stdout_byte_count-or$scopedObservation.stdout_sha256-cne$unscopedObservation.stdout_sha256){throw "GOVERNANCE_SCOPED_UNSCOPED_MISMATCH:$($item.prefix)"}
        $fields["$($item.prefix)_commit"]=$item.commit;$fields["$($item.prefix)_paths"]=@($item.paths);$fields["$($item.prefix)_scoped"]=$scopedObservation;$fields["$($item.prefix)_unscoped"]=$unscopedObservation
    }
    $fields.dispatch_metadata_digest=$Dispatch.dispatch_digest;$fields.aggregate_digest=Get-TextSha256 (Get-R24GovernanceAggregatePreimage $fields $data);$fields
}

