    $data=@(Get-R24GovernanceDeltaData);$keys=[Collections.Generic.List[string]]::new();$keys.Add('schema');foreach($item in $data){$keys.Add("$($item.prefix)_commit");$keys.Add("$($item.prefix)_paths");$keys.Add("$($item.prefix)_scoped");$keys.Add("$($item.prefix)_unscoped")};$keys.Add('dispatch_metadata_digest');$keys.Add('aggregate_digest');Assert-ExactKeys $Binding @($keys) 'GovernanceDeltaV9'
