    foreach($item in $data){foreach($suffix in @('scoped','unscoped')){$observation=$Binding["$($item.prefix)_$suffix"];Assert-ExactKeys $observation @('schema','command_id','argv','native_exit_u32','portable_exit','stdout_byte_count','stdout_sha256','stderr_byte_count','stderr_sha256','observation_digest') 'GovernanceGitObservation';Assert-SelfDigest $observation 'observation_digest'};if($Binding["$($item.prefix)_scoped"].stdout_sha256-cne$Binding["$($item.prefix)_unscoped"].stdout_sha256-or$Binding["$($item.prefix)_scoped"].stdout_byte_count-ne$Binding["$($item.prefix)_unscoped"].stdout_byte_count){throw 'GOVERNANCE_OBSERVATION_DIVERGENCE'}}
    if((Get-TextSha256 (Get-R24GovernanceAggregatePreimage $Binding $data))-cne$Binding.aggregate_digest){throw 'GOVERNANCE_AGGREGATE_DIGEST'}
