}

function Get-R24CommitObservation([string]$CommandId,[string]$Commit,[string]$ExpectedParent) {
    $argv=@('git','-C',$RepoRoot)+$GitSemanticConfig+@('cat-file','commit',$Commit)
    $run=Invoke-R24GitRun $argv $RepoRoot
    if($run.native_exit_u32-ne0-or$run.stderr_byte_count-ne0){throw 'COMMIT_OBSERVATION_COMMAND'}
