st-cne(Get-FileSha256 (Join-Path $RepoRoot 'context/waves/2026-07-28-bastion-foundation/pulses/pulse-45-wp-tst-001-r24-acceptance.md'))-or$custody.author_id-cne'REV-TST-ENTRY-AUTHOR'){throw 'PULSE_ENTRY_CUSTODY'}};[ordered]@{custody=$custody;byte_count=[uint64]$bytes.Length;sha256=Get-BytesSha256 $bytes}
