function Get-R24RawDeltaRows([byte[]]$Bytes) {
    if($Bytes.Length-eq0-or$Bytes[-1]-ne0){throw 'DELTA_RAW_TERMINATION'}
    $tokens=[Collections.Generic.List[byte[]]]::new();$start=0
    for($i=0;$i-lt$Bytes.Length;$i++){if($Bytes[$i]-eq0){$length=$i-$start;$token=[byte[]]::new($length);if($length-gt0){[Array]::Copy($Bytes,$start,$token,0,$length)};$tokens.Add($token);$start=$i+1}}
    if(($tokens.Count%2)-ne0){throw 'DELTA_RAW_ARITY'}
    $rows=[Collections.Generic.List[object]]::new();$seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);$previous=$null
    for($i=0;$i-lt$tokens.Count;$i+=2){
        $metadata=[Text.ASCIIEncoding]::new().GetString($tokens[$i]);if($metadata-cnotmatch'^:[0-7]{6} [0-7]{6} ([0-9a-f]{40}) ([0-9a-f]{40}) ([AM])$'){throw 'DELTA_RAW_METADATA'}
        $path=New-R24RawGitPath $tokens[$i+1];if(-not$seen.Add($path.content)){throw 'DELTA_RAW_DUPLICATE_PATH'}
        if($null-ne$previous){$limit=[Math]::Min($previous.Length,$tokens[$i+1].Length);$comparison=0;for($j=0;$j-lt$limit-and$comparison-eq0;$j++){$comparison=[int]$previous[$j]-[int]$tokens[$i+1][$j]};if($comparison-eq0){$comparison=$previous.Length-$tokens[$i+1].Length};if($comparison-ge0){throw 'DELTA_RAW_ORDER'}}
        $previous=$tokens[$i+1];$rows.Add([ordered]@{status=$Matches[3];path=$path;old_oid=$Matches[1];new_oid=$Matches[2]})
    }
    @($rows)
}

