function New-R24FailedAmendment([int]$Index,$Data) {
    $dispatch=New-R24ValidatorDispatch 'failed-amendment-review' "/lineage_binding/failed_amendments/$Index/review" $Data.review_schema "/lineage_binding/failed_amendments/$Index" $Data.commit
    $review=New-DigestedObject ([ordered]@{schema=$Data.review_schema;review_id="AUDIT-WP-TST-001-$($Data.rev)-AMENDMENT-001";subject_commit=$Data.commit;findings=$Data.findings;actionable_count=$Data.findings.Count;disposition='failed-retained';accepted=$false;entered=$false;authority_created=$false}) 'review_digest'
    $binding=New-DigestedObject ([ordered]@{schema='test-gate-failed-amendment.v9';wp_revision=$WpRevision;commit=$Data.commit;first_parent=$Data.parent;wp_sha256=$Data.wp;wp_blob=$Data.blob;pulse_path="context/waves/2026-07-28-bastion-foundation/pulses/$($Data.pulse)";pulse_sha256=$Data.pulse_sha;pulse_blob=$Data.pulse_blob;dispatch_metadata_digest=$dispatch.dispatch_digest;review_id=$review.review_id;review_digest=$review.review_digest;actionable_count=$review.actionable_count;disposition='failed-retained';accepted=$false;entered=$false;authority_created=$false}) 'binding_digest'
    [ordered]@{dispatch=$dispatch;review=$review;binding=$binding}
}

