function New-R24CorrectiveLineage($Acceptance,$CorrectiveEntry,$FailedAttempt,[object[]]$FailedAmendments,[object[]]$FailedGovernanceStages,$GovernanceDelta,$CompleteDelta,$CorrectiveDelta,$Implementation) {
    Assert-R24AcceptanceBinding $Acceptance;Assert-R24CorrectiveEntryBinding $CorrectiveEntry $Acceptance;Assert-R24ImplementationBinding $Implementation
    if($FailedAmendments.Count-ne8-or$FailedGovernanceStages.Count-ne2){throw 'LINEAGE_HISTORY_CARDINALITY'}
    New-DigestedObject ([ordered]@{schema='test-gate-corrective-lineage.v9';wp_revision=$WpRevision;wp_artifact_digest=$WpDigest;r24_candidate_commit=$CandidateCommit;acceptance_binding=$Acceptance;corrective_entry_binding=$CorrectiveEntry;original_r14_entry_commit='6354f5184b97923571dcd397ac9871167833e86e';original_r14_entry_pulse_digest='84bdc53fed341919db253d2799a2d7119a965fce5b505dd28df0fec840f5c035';failed_attempt=$FailedAttempt;failed_amendments=$FailedAmendments;failed_governance_stages=$FailedGovernanceStages;governance_delta=$GovernanceDelta;complete_implementation_delta=$CompleteDelta;corrective_delta=$CorrectiveDelta;corrective_implementation_commit=$Implementation.commit;corrective_implementation_tree=$Implementation.tree_digest}) 'lineage_digest'
}

function Assert-R24CorrectiveLineage($Lineage,$Implementation) {
    Assert-ExactKeys $Lineage @('schema','wp_revision','wp_artifact_digest','r24_candidate_commit','acceptance_binding','corrective_entry_binding','original_r14_entry_commit','original_r14_entry_pulse_digest','failed_attempt','failed_amendments','failed_governance_stages','governance_delta','complete_implementation_delta','corrective_delta','corrective_implementation_commit','corrective_implementation_tree','lineage_digest') 'CorrectiveLineageV9';Assert-SelfDigest $Lineage 'lineage_digest'
    if($Lineage.schema-cne'test-gate-corrective-lineage.v9'-or$Lineage.wp_revision-cne$WpRevision-or$Lineage.wp_artifact_digest-cne$WpDigest-or$Lineage.r24_candidate_commit-cne$CandidateCommit-or$Lineage.original_r14_entry_commit-cne'6354f5184b97923571dcd397ac9871167833e86e'-or$Lineage.original_r14_entry_pulse_digest-cne'84bdc53fed341919db253d2799a2d7119a965fce5b505dd28df0fec840f5c035'-or$Lineage.corrective_implementation_commit-cne$Implementation.commit-or$Lineage.corrective_implementation_tree-cne$Implementation.tree_digest-or@($Lineage.failed_amendments).Count-ne8-or@($Lineage.failed_governance_stages).Count-ne2){throw 'LINEAGE_BINDING_SUBSTITUTION'}
    Assert-R24AcceptanceBinding $Lineage.acceptance_binding;Assert-R24CorrectiveEntryBinding $Lineage.corrective_entry_binding $Lineage.acceptance_binding
    Assert-ExactKeys $Lineage.failed_attempt @('audit','binding') 'FailedAttemptEnvelope';Assert-R24FailedAttempt $Lineage.failed_attempt.audit $Lineage.failed_attempt.binding
    $amendmentData=@(Get-R24FailedAmendmentData);for($i=0;$i-lt8;$i++){Assert-ExactKeys $Lineage.failed_amendments[$i] @('dispatch','review','binding') "FailedAmendmentEnvelope[$i]";Assert-R24FailedAmendment $i $amendmentData[$i] $Lineage.failed_amendments[$i]}
    $stageData=@(Get-R24FailedStageData);for($i=0;$i-lt2;$i++){Assert-ExactKeys $Lineage.failed_governance_stages[$i] @('dispatch','binding') "FailedStageEnvelope[$i]";Assert-R24FailedStage $i $stageData[$i] $Lineage.failed_governance_stages[$i]}
    $governanceDispatch=New-R24ValidatorDispatch 'governance-delta' '/lineage_binding/governance_delta' 'test-gate-governance-delta.v9' '/lineage_binding' $null;Assert-R24GovernanceDelta $Lineage.governance_delta $governanceDispatch
    Assert-R24DeltaBinding $Lineage.complete_implementation_delta 'complete-implementation' $Lineage.original_r14_entry_commit $Implementation.commit;Assert-R24DeltaBinding $Lineage.corrective_delta 'corrective-implementation' $EntryCommit $Implementation.commit
    if((ConvertTo-CanonicalJson $Lineage.complete_implementation_delta)-cne(ConvertTo-CanonicalJson $Implementation.complete_implementation_delta)-or(ConvertTo-CanonicalJson $Lineage.corrective_delta)-cne(ConvertTo-CanonicalJson $Implementation.corrective_delta)-or$Implementation.first_parent-cne$Lineage.corrective_entry_binding.commit){throw 'LINEAGE_IMPLEMENTATION_EQUALITY'}
    Assert-R24ImplementationBinding $Implementation $Lineage
    $componentDigests=@($Lineage.failed_attempt.binding.binding_digest)+@($Lineage.failed_amendments|ForEach-Object{$_.binding.binding_digest})+@($Lineage.failed_governance_stages|ForEach-Object{$_.binding.binding_digest})+@($Lineage.governance_delta.aggregate_digest,$Lineage.complete_implementation_delta.delta_digest,$Lineage.corrective_delta.delta_digest);if(@($componentDigests|Where-Object{$_-ceq$Lineage.lineage_digest}).Count-ne0){throw 'LINEAGE_DIGEST_DOMAIN_COLLISION'}
}

