    if($Evidence.mode-notin$ModeOrder-or$Evidence.evidence_id-cne('EVID-WP-TST-001-{0}-v{1:d4}'-f$Evidence.mode,$Evidence.evidence_version)-or$Evidence.evidence_path-cne"context/waves/2026-07-28-bastion-foundation/evidence/wp-tst-001/runs/$($Evidence.mode)/$($Evidence.evidence_id).json"-or$Evidence.execution_id-cne('EXEC-WP-TST-001-{0}-v{1:d4}'-f$Evidence.mode,$Evidence.execution_evidence_version)){throw 'MODE_EVIDENCE_DERIVED_IDENTITY'}
