    if($Evidence.candidate_author_ids.Count-ne$Evidence.identity_registry.candidate_author_ids.Count-or(ConvertTo-CanonicalJson @($Evidence.candidate_author_ids))-cne(ConvertTo-CanonicalJson @($Evidence.identity_registry.candidate_author_ids))){throw 'MODE_EVIDENCE_AUTHOR_PROJECTION'}
    if(@($Evidence.allocated_targets).Count-ne@($Evidence.target_results).Count){throw 'MODE_EVIDENCE_TARGET_CARDINALITY'};for($i=0;$i-lt@($Evidence.target_results).Count;$i++){if($Evidence.allocated_targets[$i].controlled_id-cne$Evidence.target_results[$i].controlled_id-or$Evidence.allocated_targets[$i].assertion-cne$Evidence.target_results[$i].assertion){throw "MODE_EVIDENCE_TARGET_BINDING:$i"}}
    if($Evidence.ledger_binding.execution_id-cne$Evidence.execution_id-or$Evidence.ledger_binding.execution_ordinal-ne$Evidence.execution_ordinal-or$Evidence.ledger_binding.execution_evidence_version-ne$Evidence.execution_evidence_version-or$Evidence.ledger_binding.record_count-lt2-or$Evidence.ledger_binding.first_record_digest-notmatch'^[0-9a-f]{64}$'-or$Evidence.ledger_binding.last_record_digest-notmatch'^[0-9a-f]{64}$'-or$Evidence.ledger_binding.aggregate_digest-notmatch'^[0-9a-f]{64}$'){throw 'MODE_EVIDENCE_LEDGER_BINDING'}
    foreach($streamName in @('stdout','stderr')){$stream=$Evidence.observed_outputs[$streamName];if($stream.encoding-cne'base64'){throw "MODE_EVIDENCE_STREAM_ENCODING:$streamName"};$bytes=[Convert]::FromBase64String($stream.content_base64);if($bytes.Length-ne$stream.decoded_byte_count-or(Get-BytesSha256 $bytes)-cne$stream.decoded_sha256){throw "MODE_EVIDENCE_STREAM_BINDING:$streamName"}}
    $structured=$Evidence.observed_outputs.structured;$structuredJson=ConvertTo-CanonicalJson $structured.content;if($structured.encoding-cne'canonical-json'-or$structured.byte_count-ne[Text.Encoding]::UTF8.GetByteCount($structuredJson)-or$structured.sha256-cne(Get-TextSha256 $structuredJson)-or$structured.content.command_identity-cne$Evidence.command_identity-or$structured.content.result-cne$Evidence.actual.result){throw 'MODE_EVIDENCE_STRUCTURED_OUTPUT'}
