function Assert-R24NestedEvidenceClosure($Evidence) {
    Assert-ExactKeys $Evidence.execution_origin @('wp_revision','lineage_digest','execution_id','execution_ordinal','execution_evidence_version','implementation_commit','run_id','ledger_root','ledger_aggregate_digest') 'ExecutionOrigin';Assert-ExactKeys $Evidence.actual @('native_exit_u32','portable_exit','result','posture','reason','start_utc','end_utc','duration_ms') 'EvidenceActual';Assert-ExactKeys $Evidence.expected @('native_exit_u32','portable_exit','result','posture','reason') 'EvidenceExpected';Assert-ExactKeys $Evidence.resource_bounds @('wall_seconds','job_memory_bytes','process_memory_bytes','combined_stream_bytes') 'ResourceBounds';Assert-ExactKeys $Evidence.determinism_controls @('order','seed','clock','locale','retry') 'DeterminismControls'
    foreach($target in $Evidence.allocated_targets){Assert-ExactKeys $target @('controlled_id','assertion') 'AllocatedTarget'};foreach($result in $Evidence.target_results){Assert-ExactKeys $result @('controlled_id','assertion','attempt_ordinal','attempt_argv','start_record_digest','completion_record_digest','recovery_record_digest','state','reason','output_pointer') 'TargetResult';if($result.state-cnotin@('passed','failed','held','not_run')-or$result.start_record_digest-cnotmatch'^[0-9a-f]{64}$'){throw 'TARGET_RESULT_STATE'};if(($result.state-ceq'passed')-ne($null-ne$result.completion_record_digest)){throw 'TARGET_RESULT_TERMINAL'}}
