    for($version=1;$version-le$Set.set_version;$version++){
        $id=('EVID-WP-TST-001-SET-v{0:d4}'-f$version);$path="context/waves/2026-07-28-bastion-foundation/evidence/wp-tst-001/sets/$id.json";$item=if($version-eq$Set.set_version){$Set}else{Read-StrictJson (Join-Path $root $path) 'test-gate-evidence-set.v16'};Assert-R24EvidenceSet $item $root -SkipArtifactHistory
        if($item.set_id-cne$id-or$item.set_path-cne$path-or$item.set_version-ne$version-or$item.lineage_binding.lineage_digest-cne$Set.lineage_binding.lineage_digest){throw "SET_HISTORY_IDENTITY:$version"};$binding=New-R24SetBinding $item
        if($version-lt$Set.set_version){Assert-ExactKeys (@($Set.history)[$version-1]) @('set_id','set_path','set_version','set_digest') "SetHistory[$version]";if((ConvertTo-CanonicalJson (@($Set.history)[$version-1]))-cne(ConvertTo-CanonicalJson $binding)){throw "SET_HISTORY_BINDING:$version"}}
        $badPredecessor=@($item.history).Count-ne($version-1)-or($version-eq1-and$null-ne$item.predecessor_set)
        if($version-gt1){$badPredecessor=$badPredecessor-or((ConvertTo-CanonicalJson $item.predecessor_set)-cne(ConvertTo-CanonicalJson(New-R24SetBinding ($versions[$version-2]))))}
        if($badPredecessor){throw "SET_HISTORY_PREDECESSOR:$version"};for($h=0;$h-lt($version-1);$h++){if((ConvertTo-CanonicalJson (@($item.history)[$h]))-cne(ConvertTo-CanonicalJson(New-R24SetBinding ($versions[$h])))){throw "SET_HISTORY_PREFIX:$version/$h"}};$versions.Add($item)
    }
