function Assert-R24ModeReviewSuccessorShape($Predecessor,$Successor,[int]$LaneIndex,$Decision) {
    $stable=@('schema','mode','execution_id','execution_ordinal','execution_evidence_version','execution_origin','predecessor_execution','execution_history','wp_id','wp_revision','wp_artifact_digest','lineage_binding','acceptance_binding','corrective_entry_binding','implementation_binding','logical_predecessor_commit','context_rev_binding','identity_registry','candidate_author_ids','artifact_digests','trace_manifest_digest','allocated_targets','execution_phases','target_results','ledger_binding','fixture_bindings','command_identity','exact_argv','tool_versions','environment_digest','resource_bounds','determinism_controls','expected','actual','observed_outputs','rollback_plan','reproduction_plan','failure_records','counterexamples','required_review_lanes','invalidation_triggers')
