    $preCustody=[ordered]@{};$postCustody=[ordered]@{};foreach($key in @($Predecessor.post_execution_custody.Keys|Where-Object{$_-notin@('allowed_new_paths','publication_plan','custody_digest')})){$preCustody[$key]=$Predecessor.post_execution_custody[$key];$postCustody[$key]=$Successor.post_execution_custody[$key]};if((ConvertTo-CanonicalJson $preCustody)-cne(ConvertTo-CanonicalJson $postCustody)){throw 'MODE_REVIEW_EXECUTION_CUSTODY'}
