    $normalPhaseStart=Add-LedgerRecord $normal 'phase-01-start' ([ordered]@{phase_ordinal=1;phase_id='PHASE-L0Check-01';phase_kind='targets';argv=@('cargo','+1.95.0','check','--workspace','--all-targets','--locked','--offline');start_utc='2026-07-29T00:00:00.0000000+00:00'})
