function Get-SanitizedEnvironment([string]$TargetDirectory) {
    $values=[ordered]@{}
    foreach($name in $AllowedEnvironment){
        $value=[Environment]::GetEnvironmentVariable($name)
        if($name-ceq'PATH'){$cargo=(Get-Command cargo.exe -CommandType Application -ErrorAction Stop).Source;$value=@([IO.Path]::GetDirectoryName($cargo),[IO.Path]::GetDirectoryName($script:R24GitExecutable),(Join-Path $env:SYSTEMROOT 'System32')|Sort-Object -Unique -CaseSensitive)-join';'}
        if([string]::IsNullOrEmpty($value)){continue}
        $invalidCharacters=@($value.ToCharArray()|Where-Object{([int]$_ -lt 32) -or ([int]$_ -gt 126)})
        if($value.Length-gt128){continue};if($invalidCharacters.Count-ne0){throw "ENVIRONMENT_VALUE_BOUND:$name"};$values[$name]=$value
    }
    $pairs=@($values.Keys|Sort-Object -CaseSensitive|ForEach-Object{"$_=$($values[$_])"});$pairs += "CARGO_TARGET_DIR=$TargetDirectory"
    [ordered]@{values=$values;pairs=$pairs;digest=Get-CanonicalEnvironmentDigest $values}
}

