function Assert-R24Custody {
    $expected = [ordered]@{
        'docs/vtrace/WP_TST_001.md' = $WpDigest
        'context/waves/2026-07-28-bastion-foundation/pulses/pulse-44-wp-tst-001-r24-corrective-lineage-candidate.md' = '8d1a10dd862821faba0fbbc74b21a786704b8aad95417180c668be9469b89dc6'
        'context/waves/2026-07-28-bastion-foundation/pulses/pulse-45-wp-tst-001-r24-acceptance.md' = '8859dfc78a2649ed5154130d5fb61190333b0ceaab93bd712a78ca5c9aa7b49c'
        'context/waves/2026-07-28-bastion-foundation/pulses/pulse-46-wp-tst-001-r24-corrective-entry.md' = '29b972059647f34329e2d81dba7f37ccd85248c13dea8ceb3ece07e1596db5c1'
    }
