    if($parent-cne$AcceptanceCommit){throw 'R24_ACCEPTANCE_PARENT_MISMATCH'}
    $acceptanceParent=Invoke-R24GitText 'custody_acceptance_parent' @('git','-C',$RepoRoot,'rev-parse',"$AcceptanceCommit^") $RepoRoot
