}

function Assert-R24ImplementationDelta {
    $changedText=Invoke-R24GitText 'implementation_delta_names' @('git','-C',$RepoRoot,'diff','--name-only','--no-renames',$EntryCommit,'--') $RepoRoot
    $changed=if([string]::IsNullOrEmpty($changedText)){@()}else{@($changedText.Split("`n",[StringSplitOptions]::RemoveEmptyEntries)|ForEach-Object{$_.TrimEnd("`r")})}
    $unexpected = @($changed | Where-Object { $_ -notin $ImplementationPaths })
    if ($unexpected.Count -ne 0) { throw "R24_PATH_OUTSIDE_ALLOWLIST:$($unexpected -join ',')" }
    if ($changed.Count -eq 0) { throw 'R24_EMPTY_IMPLEMENTATION_DELTA' }
}

function Invoke-R24ValidateOnly {
