    $governanceDispatch=New-R24ValidatorDispatch 'governance-delta' '/lineage_binding/governance_delta' 'test-gate-governance-delta.v9' '/lineage_binding' $null
    $governance=New-R24GovernanceDelta $governanceDispatch
    $observation=Get-R24CommitObservation 'corrective_implementation_commit_object' $commit $EntryCommit
    $implementation=New-R24ImplementationBinding $commit $observation.tree $EntryCommit $observation $failedAttempt.binding.binding_digest @($failedAmendments|ForEach-Object{$_.binding.binding_digest}) @($failedStages|ForEach-Object{$_.binding.binding_digest}) $governance.aggregate_digest $complete $corrective $noExtra $preflight
    $acceptance=New-R24AcceptanceBinding;$entry=New-R24CorrectiveEntryBinding $acceptance
    $lineage=New-R24CorrectiveLineage $acceptance $entry $failedAttempt @($failedAmendments) @($failedStages) $governance $complete $corrective $implementation

    $registry=New-R24IdentityRegistry @(New-R24AuthorBinding 'corrective_implementation_commit' $commit (Get-TextSha256 $commit) $lineage.lineage_digest 'REV-TST-IMPLEMENTATION-AUTHOR' 'REV-TST-GOVERNANCE-CONTROLLER')
    $authentications=[Collections.Generic.List[object]]::new()
    for($lane=0;$lane-lt22;$lane++){$auth=New-R24ReviewAuthentication $lane ('REV-TST-FINAL-REVIEWER-L{0:d2}'-f$lane) 'REV-TST-GOVERNANCE-CONTROLLER' $lineage.lineage_digest $registry;Assert-R24ReviewAuthentication $auth $lane $lineage.lineage_digest $registry;$authentications.Add($auth)}
    $modeDecisions=[Collections.Generic.List[object]]::new()
    foreach($selected in $ModeOrder){$decisions=[Collections.Generic.List[object]]::new();for($lane=0;$lane-lt22;$lane++){$decision=New-R24PassDecision $selected $lane 1 $authentications[$lane] $null;Assert-R24PassDecision $decision $selected $lane $authentications[$lane] $null $registry;$decisions.Add($decision)};$modeDecisions.Add([ordered]@{mode=$selected;decisions=@($decisions)})}
    $setDecisions=[Collections.Generic.List[object]]::new();for($lane=0;$lane-lt22;$lane++){$decision=New-R24PassDecision 'SET' $lane 1 $authentications[$lane] $null;Assert-R24PassDecision $decision 'SET' $lane $authentications[$lane] $null $registry;$setDecisions.Add($decision)}
    $bundle=New-DigestedObject ([ordered]@{schema='test-gate-review-bundle.v2';lineage_digest=$lineage.lineage_digest;authentications=@($authentications);mode_decisions=@($modeDecisions);set_decisions=@($setDecisions)}) 'bundle_digest'

    $root=New-ExternalDirectory 'bastion-tst-final-bundle' $external
