    Write-CreateNewCanonical $implementationPath $implementation|Out-Null;Write-CreateNewCanonical $lineagePath $lineage|Out-Null;Write-CreateNewCanonical $reviewPath $bundle|Out-Null
    Assert-R24ExternalFileDispatch $implementationPath 'implementation-binding' 'test-gate-implementation-binding.v10' $null $commit|Out-Null;Assert-R24ImplementationBinding (Read-StrictJson $implementationPath 'test-gate-implementation-binding.v10')
