    Assert-R24ExternalFileDispatch $reviewPath 'review-bundle' 'test-gate-review-bundle.v2' $lineagePath $commit|Out-Null
    [ordered]@{schema='test-gate-final-commit-bundle-preparation.v1';implementation_commit=$commit;implementation_binding_path=$implementationPath;implementation_binding_digest=$implementation.binding_digest;lineage_binding_path=$lineagePath;lineage_digest=$lineage.lineage_digest;review_bundle_path=$reviewPath;review_bundle_digest=$bundle.bundle_digest;reviewer_count=$authentications.Count;mode_count=$modeDecisions.Count;set_decision_count=$setDecisions.Count;status='prepared'}
