    if([string]::IsNullOrWhiteSpace($ImplementationCommit)-or$ImplementationCommit-cnotmatch'^[0-9a-f]{40}$'-or$ImplementationCommit-ceq$EntryCommit){throw 'CANONICAL_IMPLEMENTATION_COMMIT'}
    if([string]::IsNullOrWhiteSpace($ImplementationBindingPath)-or-not[IO.File]::Exists($ImplementationBindingPath)-or[string]::IsNullOrWhiteSpace($LineageBindingPath)-or-not[IO.File]::Exists($LineageBindingPath)){throw 'CANONICAL_BINDING_PATH'}
