    Assert-R24ExternalFileDispatch $LineageBindingPath 'corrective-lineage' 'test-gate-corrective-lineage.v9' $ImplementationBindingPath $ImplementationCommit|Out-Null;$lineage=Read-StrictJson ([IO.Path]::GetFullPath($LineageBindingPath)) 'test-gate-corrective-lineage.v9';Assert-R24CorrectiveLineage $lineage $implementation
    if($implementation.commit-cne$ImplementationCommit-or$lineage.corrective_implementation_commit-cne$ImplementationCommit-or$lineage.corrective_implementation_tree-cne$implementation.tree_digest-or(ConvertTo-CanonicalJson $lineage.acceptance_binding)-cne(ConvertTo-CanonicalJson(New-R24AcceptanceBinding))-or(ConvertTo-CanonicalJson $lineage.corrective_entry_binding)-cne(ConvertTo-CanonicalJson(New-R24CorrectiveEntryBinding $lineage.acceptance_binding))){throw 'CANONICAL_LINEAGE_EQUALITY'}
