    $head=Invoke-R24GitText 'canonical_implementation_head' @('git','-C',$RepoRoot,'rev-parse','HEAD') $RepoRoot;if($head-cne$ImplementationCommit){throw 'CANONICAL_IMPLEMENTATION_NOT_HEAD'};$actualObservation=Get-R24CommitObservation 'corrective_implementation_commit_object' $ImplementationCommit $EntryCommit;if((ConvertTo-CanonicalJson $actualObservation)-cne(ConvertTo-CanonicalJson $implementation.commit_observation)){throw 'CANONICAL_COMMIT_OBSERVATION'}
