    $repository=[IO.Path]::GetFullPath($RepoRoot).TrimEnd([IO.Path]::DirectorySeparatorChar);$watched=[IO.Path]::GetFullPath($Session.roots.worktree).TrimEnd([IO.Path]::DirectorySeparatorChar)
