    $head=Invoke-R24GitText 'publication_head' @('git','-C',$RepoRoot,'rev-parse','HEAD') $RepoRoot;$parent=Invoke-R24GitText 'publication_parent' @('git','-C',$RepoRoot,'rev-parse','HEAD^') $RepoRoot;if($head-cne$ImplementationCommit-or$parent-cne$EntryCommit){throw 'CANONICAL_REPOSITORY_PUBLICATION_LINEAGE'}
    [ordered]@{root=$repository;source='worktree';authorized=$true;implementation_commit=$Guard.implementation.commit;binding_digest=$Guard.implementation.binding_digest}
}

