function Assert-R24PromotableModeChain($Pipeline) {
    $evidence=$Pipeline.evidence;$publication=$Pipeline.publication;Assert-R24ModeEvidenceEnvelope $evidence;Assert-R24PublicationReceipt $publication.receipt $evidence;Assert-R24PublicationFinalization $publication.finalization $publication.receipt $evidence
