    if((ConvertTo-CanonicalJson $publication.post_evidence_snapshot)-cne(ConvertTo-CanonicalJson $publication.receipt.post_evidence_snapshot)-or(ConvertTo-CanonicalJson $publication.post_receipt_snapshot)-cne(ConvertTo-CanonicalJson $publication.finalization.post_receipt_snapshot)-or$publication.post_finalization_snapshot.snapshot_digest-cne$publication.finalization.expected_post_finalization_snapshot_digest-or$Pipeline.final_watch_event_count-ne$publication.finalization.expected_final_watch_event_count-or$Pipeline.final_watch_digest-cne$publication.finalization.expected_final_watch_digest){throw 'PROMOTABLE_MODE_FINAL_BINDING'}
    $events=@($Pipeline.final_watch_events);if($events.Count-ne$Pipeline.final_watch_event_count-or(Get-TextSha256 (($events|ForEach-Object{(ConvertTo-CanonicalJson $_)+"`n"})-join''))-cne$Pipeline.final_watch_digest){throw 'PROMOTABLE_MODE_LIVE_EVENT_BINDING'};$plan=$evidence.post_execution_custody.publication_plan;$finalEvents=@($events|Where-Object{$_.source-ceq$plan.finalization_self_event.source-and$_.action-ceq$plan.finalization_self_event.action-and(ConvertFrom-R24RawGitPath $_.raw_path)-ceq$plan.finalization_path});if($finalEvents.Count-ne1-or$null-ne$finalEvents[0].content_sha256){throw 'PROMOTABLE_MODE_SELF_EVENT'};$stopEvents=@($events|Where-Object action -eq 'watch-stop');if((ConvertTo-CanonicalJson @($stopEvents|ForEach-Object{[ordered]@{source=$_.source;action=$_.action}}))-cne(ConvertTo-CanonicalJson @($plan.watch_stop_event))){throw 'PROMOTABLE_MODE_STOP_EVENTS'}
    $ledgerRead=Assert-LedgerChain $Pipeline.worker.ledger_physical_root;foreach($key in @('execution_id','execution_ordinal','execution_evidence_version','run_id','run_attempt','first_record_digest','last_record_digest','record_count','aggregate_digest')){if($ledgerRead.binding[$key]-cne$evidence.ledger_binding[$key]){throw "PROMOTABLE_MODE_LEDGER_FILE_BINDING:$key"}}
    $evidenceRead=Read-StrictJson $publication.evidence_write.physical_path 'test-gate-evidence.v17';$receiptRead=Read-StrictJson $publication.receipt_write.physical_path 'test-gate-publication-receipt.v7';$finalizationRead=Read-StrictJson $publication.finalization_write.physical_path 'test-gate-publication-finalization.v7';Assert-R24ModeEvidenceEnvelope $evidenceRead;Assert-R24PublicationReceipt $receiptRead $evidenceRead;Assert-R24PublicationFinalization $finalizationRead $receiptRead $evidenceRead
    if($evidenceRead.evidence_digest-cne$evidence.evidence_digest-or$receiptRead.receipt_digest-cne$publication.receipt.receipt_digest-or$finalizationRead.finalization_digest-cne$publication.finalization.finalization_digest){throw 'PROMOTABLE_MODE_FILE_BINDING'}
}

function New-R24GuardedCanonicalSet([object[]]$ModePipelines) {
    if($ModePipelines.Count-ne16){throw 'CANONICAL_SET_MODE_CARDINALITY'};$records=[Collections.Generic.List[object]]::new()
