        $allPaths=[Collections.Generic.List[string]]::new();$allPaths.Add($set.set_path);for($version=2;$version-le23;$version++){$allPaths.Add("context/waves/2026-07-28-bastion-foundation/evidence/wp-tst-001/sets/EVID-WP-TST-001-SET-v$($version.ToString('0000')).json")};$session.repository_publication_authorized=$true;$session.repository_publication_paths=Get-R24PublicationMutationAllowlist @($allPaths);Set-R24PublicationWatchMode $session;Write-R24CanonicalLogicalArtifact $session $binding.root $set.set_path $set|Out-Null
        for($lane=0;$lane-lt22;$lane++){$decision=$Bundle.set_decisions[$lane];Assert-R24DecisionAdmission $decision 'SET' $lane $Bundle.authentications[$lane] $set.reviewer_decisions[$lane] $set.identity_registry;$lanePipelines=@($LanePipelineSets[$lane]);$successor=New-R24SetReviewSuccessor $set $lane $decision $lanePipelines;Assert-R24SetReviewSuccessorShape $set $successor $lane $decision $lanePipelines;Assert-R24EvidenceSet $successor $RepoRoot;$supervisorPlannedSets.Add($successor);Write-R24CanonicalLogicalArtifact $session $binding.root $successor.set_path $successor|Out-Null;$set=$successor}
        $freshSet=(Get-ObservedPreflight $RepoRoot $Guard.implementation.commit).preflight;if($freshSet.status-cne'pass'){throw 'SET_FRESH_PREFLIGHT'};Complete-R24SetDeliveryBarrier $session $freshSet @($allPaths) @($supervisorPlannedSets);Stop-R24FiveRootCustodySession $session|Out-Null;if($set.status-cne'full'-or$set.review_completeness-cne'full'){throw 'REVIEWED_SET_NOT_FULL'};Assert-R24EvidenceSet $set $RepoRoot;$set
    } finally {if(-not$session.stopped){Stop-R24FiveRootCustodySession $session -Abort|Out-Null}}
}

function Invoke-R24FinalCommitHarness {
    if(-not$EnableCanonicalPipeline-or-not$EnableRepositoryPublication){throw 'FINAL_HARNESS_ENABLE_REQUIRED'};$pipelines=[Collections.Generic.List[object]]::new();$reviewed=[Collections.Generic.List[object]]::new();$lanePipelineSets=[Collections.Generic.List[object]]::new();$failures=[Collections.Generic.List[object]]::new();$set=$null;$bundle=$null
    try{$guard=Assert-R24CanonicalImplementationGuard;if([string]::IsNullOrWhiteSpace($ReviewBundlePath)-or-not[IO.File]::Exists($ReviewBundlePath)){throw 'AUTHENTICATED_REVIEW_BUNDLE_REQUIRED'};Assert-R24ExternalFileDispatch $ReviewBundlePath 'review-bundle' 'test-gate-review-bundle.v2' $LineageBindingPath $ImplementationCommit|Out-Null;$bundle=Read-StrictJson ([IO.Path]::GetFullPath($ReviewBundlePath)) 'test-gate-review-bundle.v2';Assert-ExactKeys $bundle @('schema','lineage_digest','authentications','mode_decisions','set_decisions','bundle_digest') 'ReviewBundleV2';Assert-SelfDigest $bundle 'bundle_digest';if($bundle.lineage_digest-cne$guard.lineage.lineage_digest-or@($bundle.authentications).Count-ne22-or@($bundle.mode_decisions).Count-ne16-or@($bundle.set_decisions).Count-ne22){throw 'REVIEW_BUNDLE_CARDINALITY'};$reviewers=@($bundle.authentications|ForEach-Object{$_.reviewer_id});if(@($reviewers|Where-Object{$_-cnotmatch'^REV-[A-Z0-9][A-Z0-9-]{0,59}$'}).Count-ne0-or@($reviewers|Sort-Object -Unique -CaseSensitive).Count-ne22){throw 'REVIEW_BUNDLE_REVIEWER_BIJECTION'};for($i=0;$i-lt16;$i++){Assert-ExactKeys $bundle.mode_decisions[$i] @('mode','decisions') "ReviewBundleMode[$i]";if($bundle.mode_decisions[$i].mode-cne$ModeOrder[$i]-or@($bundle.mode_decisions[$i].decisions).Count-ne22){throw "REVIEW_BUNDLE_MODE:$i"}}}catch{$failures.Add([ordered]@{mode='BUNDLE';reason=$_.Exception.Message})}
    if($failures.Count-eq0){foreach($selected in $ModeOrder){try{$pipeline=Invoke-R24GuardedCanonicalPipeline $selected;if(-not$pipeline.publication.promotable){throw 'publication-nonpromotable'};$pipelines.Add($pipeline)}catch{$failures.Add([ordered]@{mode=$selected;reason=$_.Exception.Message});break}}}
    if($failures.Count-eq0-and$pipelines.Count-eq16){$current=@($pipelines);for($lane=0;$lane-lt22;$lane++){try{for($i=0;$i-lt16;$i++){$current[$i]=Invoke-R24ModeReviewSuccessorPipeline $current[$i] $bundle.mode_decisions[$i].decisions[$lane] $bundle.authentications[$lane] $lane $guard (Assert-ExternalDryRunRoot $EvidenceRoot)};$lanePipelineSets.Add(@($current))}catch{$failures.Add([ordered]@{mode="LANE-$lane";reason=$_.Exception.Message});break}};if($failures.Count-eq0){foreach($item in $current){$reviewed.Add($item)}}}
    if($failures.Count-eq0-and$reviewed.Count-eq16){try{$set=New-R24ReviewedCanonicalSet @($pipelines) @($lanePipelineSets) $bundle $guard (Assert-ExternalDryRunRoot $EvidenceRoot)}catch{$failures.Add([ordered]@{mode='SET';reason=$_.Exception.Message});$set=$null}}
